## 5. WordToMD Converter Implementation

### 5.1 Main Converter (Streaming, No AST)

```swift
// Sources/WordToMD/WordConverter.swift
import Foundation
import MacDocCore
import ZIPFoundation

public struct WordConverter: DocumentConverter {
    public static let sourceFormat = "docx"

    public init() {}

    public func convert<W: StreamingOutput>(
        input: URL,
        output: inout W,
        options: ConversionOptions
    ) throws {
        // 1. Unzip DOCX to temp directory
        let tempDir = try ZipHelper.unzip(input)
        defer { ZipHelper.cleanup(tempDir) }

        // 2. Load styles for heading detection
        let styles = try loadStyles(from: tempDir)
        let styleResolver = StyleResolver(styles: styles)

        // 3. Load numbering definitions for list detection
        let numbering = try loadNumbering(from: tempDir)
        let listParser = ListParser(numbering: numbering)

        // 4. Stream-process document.xml
        let documentURL = tempDir.appendingPathComponent("word/document.xml")
        let documentData = try Data(contentsOf: documentURL)
        let documentXML = try XMLDocument(data: documentData)

        // 5. Optional frontmatter
        if options.includeFrontmatter {
            try writeFrontmatter(from: tempDir, output: &output)
        }

        // 6. Process body elements in order (streaming)
        let bodyNodes = try documentXML.nodes(forXPath: "//*[local-name()='body']/*")

        for node in bodyNodes {
            guard let element = node as? XMLElement else { continue }

            switch element.localName {
            case "p":
                try processParagraph(
                    element,
                    styleResolver: styleResolver,
                    listParser: listParser,
                    output: &output,
                    options: options
                )
            case "tbl":
                try processTable(element, output: &output, options: options)
            default:
                break  // Skip unknown elements
            }
        }
    }
}
```

### 5.2 Paragraph Parser (Streaming)

```swift
// Sources/WordToMD/Parsers/ParagraphParser.swift
import Foundation
import MacDocCore

extension WordConverter {
    func processParagraph<W: StreamingOutput>(
        _ element: XMLElement,
        styleResolver: StyleResolver,
        listParser: ListParser,
        output: inout W,
        options: ConversionOptions
    ) throws {
        // Extract paragraph properties
        let pPr = element.elements(forName: "w:pPr").first
        let styleId = pPr?.elements(forName: "w:pStyle").first?
            .attribute(forName: "w:val")?.stringValue

        // Check if heading
        if let level = styleResolver.headingLevel(for: styleId) {
            let text = try extractFormattedText(from: element)
            try output.writeLine(String(repeating: "#", count: level) + " " + text)
            try output.writeBlankLine()
            return
        }

        // Check if list item
        if let listInfo = listParser.parseListInfo(from: pPr) {
            let text = try extractFormattedText(from: element)
            let prefix = listInfo.isOrdered 
                ? "\(listInfo.number). " 
                : "- "
            let indent = String(repeating: "  ", count: listInfo.level)
            try output.writeLine(indent + prefix + text)
            return
        }

        // Regular paragraph
        let text = try extractFormattedText(from: element)
        if !text.isEmpty {
            try output.writeLine(text)
            try output.writeBlankLine()
        }
    }

    /// Extract text with inline formatting (bold/italic)
    private func extractFormattedText(from paragraph: XMLElement) throws -> String {
        var result = ""

        for run in paragraph.elements(forName: "w:r") {
            let rPr = run.elements(forName: "w:rPr").first
            let isBold = rPr?.elements(forName: "w:b").first != nil
            let isItalic = rPr?.elements(forName: "w:i").first != nil

            var text = ""
            for t in run.elements(forName: "w:t") {
                text += t.stringValue ?? ""
            }

            // Apply formatting
            if !text.isEmpty {
                if isBold && isItalic {
                    result += "***\(text)***"
                } else if isBold {
                    result += "**\(text)**"
                } else if isItalic {
                    result += "_\(text)_"
                } else {
                    result += text
                }
            }
        }

        return result
    }
}
```

### 5.3 Table Parser (Streaming)

```swift
// Sources/WordToMD/Parsers/TableParser.swift
import Foundation
import MacDocCore

extension WordConverter {
    func processTable<W: StreamingOutput>(
        _ element: XMLElement,
        output: inout W,
        options: ConversionOptions
    ) throws {
        var rows: [[String]] = []

        // Parse all rows
        for tr in element.elements(forName: "w:tr") {
            var cells: [String] = []
            for tc in tr.elements(forName: "w:tc") {
                let cellText = try extractCellText(from: tc)
                cells.append(cellText)
            }
            rows.append(cells)
        }

        guard !rows.isEmpty else { return }

        // Determine column count (handle ragged tables)
        let columnCount = rows.map { $0.count }.max() ?? 0
        guard columnCount > 0 else { return }

        // Normalize rows to same column count
        let normalizedRows = rows.map { row -> [String] in
            if row.count < columnCount {
                return row + Array(repeating: "", count: columnCount - row.count)
            }
            return row
        }

        // Output header row
        let headerRow = normalizedRows[0]
        try output.writeLine("| " + headerRow.joined(separator: " | ") + " |")

        // Output separator
        let separator = headerRow.map { _ in "---" }
        try output.writeLine("|" + separator.joined(separator: "|") + "|")

        // Output data rows
        for row in normalizedRows.dropFirst() {
            try output.writeLine("| " + row.joined(separator: " | ") + " |")
        }

        try output.writeBlankLine()
    }

    private func extractCellText(from cell: XMLElement) throws -> String {
        var text = ""
        for p in cell.elements(forName: "w:p") {
            let paragraphText = try extractFormattedText(from: p)
            if !text.isEmpty && !paragraphText.isEmpty {
                text += " "  // Join multiple paragraphs with space
            }
            text += paragraphText
        }
        // Escape pipe characters in cell content
        return text.replacingOccurrences(of: "|", with: "\\|")
    }
}
```

### 5.4 Style Resolver

```swift
// Sources/WordToMD/Parsers/StyleResolver.swift
import Foundation

/// Resolves Word styles to Markdown elements
struct StyleResolver {
    private let styles: [String: StyleInfo]

    struct StyleInfo {
        let name: String
        let basedOn: String?
    }

    init(styles: [String: StyleInfo]) {
        self.styles = styles
    }

    /// Returns heading level (1-6) if style is a heading, nil otherwise
    func headingLevel(for styleId: String?) -> Int? {
        guard let styleId = styleId else { return nil }

        // Direct match for standard heading styles
        let headingPatterns: [(String, Int)] = [
            ("Heading1", 1), ("heading 1", 1), ("Heading 1", 1),
            ("Heading2", 2), ("heading 2", 2), ("Heading 2", 2),
            ("Heading3", 3), ("heading 3", 3), ("Heading 3", 3),
            ("Heading4", 4), ("heading 4", 4), ("Heading 4", 4),
            ("Heading5", 5), ("heading 5", 5), ("Heading 5", 5),
            ("Heading6", 6), ("heading 6", 6), ("Heading 6", 6),
            ("Title", 1), ("Subtitle", 2),
        ]

        for (pattern, level) in headingPatterns {
            if styleId.lowercased() == pattern.lowercased() {
                return level
            }
        }

        // Check basedOn chain
        if let info = styles[styleId], let basedOn = info.basedOn {
            return headingLevel(for: basedOn)
        }

        return nil
    }
}
```

### 5.5 List Parser

```swift
// Sources/WordToMD/Parsers/ListParser.swift
import Foundation

/// Parses Word numbering to determine list type and level
struct ListParser {
    private let numbering: NumberingInfo

    struct NumberingInfo {
        let abstractNums: [Int: AbstractNum]
        let nums: [Int: Int]  // numId -> abstractNumId
    }

    struct AbstractNum {
        let levels: [Int: LevelInfo]
    }

    struct LevelInfo {
        let format: String  // "bullet", "decimal", etc.
    }

    init(numbering: NumberingInfo) {
        self.numbering = numbering
    }

    struct ListInfo {
        let isOrdered: Bool
        let level: Int
        let number: Int
    }

    func parseListInfo(from pPr: XMLElement?) -> ListInfo? {
        guard let numPr = pPr?.elements(forName: "w:numPr").first else {
            return nil
        }

        guard let numIdStr = numPr.elements(forName: "w:numId").first?
                .attribute(forName: "w:val")?.stringValue,
              let numId = Int(numIdStr),
              numId > 0 else {
            return nil
        }

        let level = numPr.elements(forName: "w:ilvl").first?
            .attribute(forName: "w:val")?.stringValue
            .flatMap { Int($0) } ?? 0

        // Determine if ordered or unordered
        let isOrdered: Bool
        if let abstractNumId = numbering.nums[numId],
           let abstractNum = numbering.abstractNums[abstractNumId],
           let levelInfo = abstractNum.levels[level] {
            isOrdered = levelInfo.format != "bullet"
        } else {
            isOrdered = false
        }

        return ListInfo(isOrdered: isOrdered, level: level, number: 1)
    }
}
```

