## 3. Core Protocol Design (Streaming Architecture)

### 3.1 StreamingOutput Protocol

```swift
// Sources/MacDocCore/Protocols/StreamingOutput.swift
import Foundation

/// Protocol for streaming Markdown output - writes chunks as they're processed
public protocol StreamingOutput {
    /// Write a chunk of Markdown text
    mutating func write(_ text: String) throws

    /// Write a line followed by newline
    mutating func writeLine(_ text: String) throws

    /// Write blank line for paragraph separation
    mutating func writeBlankLine() throws

    /// Flush any buffered content
    mutating func flush() throws
}

/// Default implementations
public extension StreamingOutput {
    mutating func writeLine(_ text: String) throws {
        try write(text + "\n")
    }

    mutating func writeBlankLine() throws {
        try write("\n")
    }
}
```

### 3.2 MarkdownWriter Implementations

```swift
// Sources/MacDocCore/Protocols/MarkdownWriter.swift
import Foundation

/// Writes Markdown to a file handle (supports stdout)
public struct FileMarkdownWriter: StreamingOutput {
    private let fileHandle: FileHandle

    public init(fileHandle: FileHandle = .standardOutput) {
        self.fileHandle = fileHandle
    }

    public init(outputPath: URL) throws {
        FileManager.default.createFile(atPath: outputPath.path, contents: nil)
        guard let handle = FileHandle(forWritingAtPath: outputPath.path) else {
            throw ConversionError.cannotCreateOutput(outputPath.path)
        }
        self.fileHandle = handle
    }

    public func write(_ text: String) throws {
        guard let data = text.data(using: .utf8) else {
            throw ConversionError.encodingError
        }
        try fileHandle.write(contentsOf: data)
    }

    public func flush() throws {
        try fileHandle.synchronize()
    }
}

/// Accumulates Markdown in memory (for testing or small files)
public struct StringMarkdownWriter: StreamingOutput {
    public private(set) var content: String = ""

    public init() {}

    public mutating func write(_ text: String) throws {
        content += text
    }

    public func flush() throws {
        // No-op for string writer
    }
}
```

### 3.3 DocumentConverter Protocol

```swift
// Sources/MacDocCore/Protocols/DocumentConverter.swift
import Foundation

/// Protocol for document converters - streaming, no intermediate AST
public protocol DocumentConverter {
    /// Source file format identifier
    static var sourceFormat: String { get }

    /// Convert document to Markdown, streaming output
    func convert<W: StreamingOutput>(
        input: URL,
        output: inout W,
        options: ConversionOptions
    ) throws
}

/// Extension for convenience methods
public extension DocumentConverter {
    /// Convert to string (for testing)
    func convertToString(input: URL, options: ConversionOptions = .default) throws -> String {
        var writer = StringMarkdownWriter()
        try convert(input: input, output: &writer, options: options)
        return writer.content
    }

    /// Convert to file
    func convertToFile(input: URL, output: URL, options: ConversionOptions = .default) throws {
        var writer = try FileMarkdownWriter(outputPath: output)
        try convert(input: input, output: &writer, options: options)
        try writer.flush()
    }
}
```

