## 4. CLI Interface Design (ArgumentParser)

```swift
// Sources/MacDocCLI/MacDoc.swift
import ArgumentParser
import Foundation
import MacDocCore
import WordToMD

@main
struct MacDoc: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "macdoc",
        abstract: "Native macOS document to Markdown converter",
        version: "0.1.0",
        subcommands: [Word.self],
        defaultSubcommand: nil
    )
}

// MARK: - Word Subcommand
extension MacDoc {
    struct Word: AsyncParsableCommand {
        static let configuration = CommandConfiguration(
            commandName: "word",
            abstract: "Convert Word (.docx) to Markdown"
        )

        @Argument(help: "Input .docx file path")
        var input: String

        @Option(name: [.short, .long], help: "Output file path (default: stdout)")
        var output: String?

        @Flag(name: .long, help: "Include document properties as YAML frontmatter")
        var frontmatter: Bool = false

        @Flag(name: .long, help: "Convert soft line breaks to hard breaks")
        var hardBreaks: Bool = false

        mutating func run() async throws {
            let inputURL = URL(fileURLWithPath: input)

            guard FileManager.default.fileExists(atPath: inputURL.path) else {
                throw ValidationError("Input file not found: \(input)")
            }

            let options = ConversionOptions(
                includeFrontmatter: frontmatter,
                hardLineBreaks: hardBreaks,
                tableStyle: .pipe,
                headingStyle: .atx
            )

            let converter = WordConverter()

            if let outputPath = output {
                let outputURL = URL(fileURLWithPath: outputPath)
                try converter.convertToFile(input: inputURL, output: outputURL, options: options)
            } else {
                var writer = FileMarkdownWriter(fileHandle: .standardOutput)
                try converter.convert(input: inputURL, output: &writer, options: options)
            }
        }
    }
}
```

