import Foundation

/// 段落 (Paragraph) - Word 文件的基本結構單元
struct Paragraph {
    var runs: [Run]
    var properties: ParagraphProperties
    var hasPageBreak: Bool = false      // 是否為分頁符段落
    var bookmarks: [Bookmark] = []      // 段落內的書籤
    var hyperlinks: [Hyperlink] = []    // 段落內的超連結
    var commentIds: [Int] = []          // 段落關聯的註解 ID
    var footnoteIds: [Int] = []         // 段落內的腳註 ID
    var endnoteIds: [Int] = []          // 段落內的尾註 ID

    init(runs: [Run] = [], properties: ParagraphProperties = ParagraphProperties()) {
        self.runs = runs
        self.properties = properties
    }

    /// 便利初始化器：直接用文字建立段落
    init(text: String, properties: ParagraphProperties = ParagraphProperties()) {
        self.runs = [Run(text: text)]
        self.properties = properties
    }

    /// 取得段落純文字
    func getText() -> String {
        var text = runs.map { $0.text }.joined()
        // 加入超連結文字
        for hyperlink in hyperlinks {
            text += hyperlink.text
        }
        return text
    }
}

// MARK: - Paragraph Properties

/// 段落格式屬性
struct ParagraphProperties {
    var alignment: Alignment?
    var spacing: Spacing?
    var indentation: Indentation?
    var style: String?                  // 樣式名稱 (e.g., "Heading1")
    var numbering: NumberingInfo?       // 編號/項目符號
    var keepNext: Bool = false          // 與下段同頁
    var keepLines: Bool = false         // 段落不分頁
    var pageBreakBefore: Bool = false   // 段落前分頁
    var sectionBreak: SectionBreakType? // 分節符類型
    var border: ParagraphBorder?        // 段落邊框
    var shading: ParagraphShading?      // 段落底色

    init() {}

    /// 合併格式（覆蓋非 nil 值）
    mutating func merge(with other: ParagraphProperties) {
        if let alignment = other.alignment { self.alignment = alignment }
        if let spacing = other.spacing { self.spacing = spacing }
        if let indentation = other.indentation { self.indentation = indentation }
        if let style = other.style { self.style = style }
        if let numbering = other.numbering { self.numbering = numbering }
        if other.keepNext { self.keepNext = true }
        if other.keepLines { self.keepLines = true }
        if other.pageBreakBefore { self.pageBreakBefore = true }
        if let sectionBreak = other.sectionBreak { self.sectionBreak = sectionBreak }
        if let border = other.border { self.border = border }
        if let shading = other.shading { self.shading = shading }
    }
}

// MARK: - Supporting Types

/// 對齊方式
enum Alignment: String, Codable {
    case left = "left"
    case center = "center"
    case right = "right"
    case both = "both"      // 左右對齊（兩端對齊）
    case distribute = "distribute"  // 分散對齊
}

/// 段落對齊（Alignment 的別名）
typealias ParagraphAlignment = Alignment

/// 段落間距
struct Spacing {
    var before: Int?        // 段前間距 (1/20 點，twips)
    var after: Int?         // 段後間距 (1/20 點)
    var line: Int?          // 行高 (1/240 點 或 百分比)
    var lineRule: LineRule? // 行高規則

    init(before: Int? = nil, after: Int? = nil, line: Int? = nil, lineRule: LineRule? = nil) {
        self.before = before
        self.after = after
        self.line = line
        self.lineRule = lineRule
    }

    /// 便利方法：建立點數間距
    static func points(before: Double? = nil, after: Double? = nil, lineSpacing: Double? = nil) -> Spacing {
        var spacing = Spacing()
        if let before = before {
            spacing.before = Int(before * 20)  // 轉換為 twips
        }
        if let after = after {
            spacing.after = Int(after * 20)
        }
        if let lineSpacing = lineSpacing {
            spacing.line = Int(lineSpacing * 240)  // 固定行高
            spacing.lineRule = .exact
        }
        return spacing
    }
}

/// 行高規則
enum LineRule: String, Codable {
    case auto = "auto"          // 單行/1.5行/雙行
    case exact = "exact"        // 固定行高
    case atLeast = "atLeast"    // 最小行高
}

import Foundation

/// 文字運行 (Run) - Word 文件中的最小文字單元
/// 一個 Run 包含具有相同格式的連續文字
struct Run {
    var text: String
    var properties: RunProperties
    var drawing: Drawing?  // 圖片繪圖元素
    var rawXML: String?    // 原始 XML（用於欄位代碼、SDT 等進階功能）

    init(text: String, properties: RunProperties = RunProperties()) {
        self.text = text
        self.properties = properties
        self.drawing = nil
        self.rawXML = nil
    }
}

// MARK: - Run Properties

/// Run 格式屬性
struct RunProperties {
    var bold: Bool = false
    var italic: Bool = false
    var underline: UnderlineType?
    var strikethrough: Bool = false
    var fontSize: Int?              // 半點 (24 = 12pt)
    var fontName: String?
    var color: String?              // RGB hex (e.g., "FF0000")
    var highlight: HighlightColor?
    var verticalAlign: VerticalAlign?
    var characterSpacing: CharacterSpacing?  // 字元間距
    var textEffect: TextEffect?              // 文字效果
    var rawXML: String?                      // 原始 XML（用於進階功能如 SDT）

    init() {}

    init(bold: Bool = false,
         italic: Bool = false,
         underline: UnderlineType? = nil,
         strikethrough: Bool = false,
         fontSize: Int? = nil,
         fontName: String? = nil,
         color: String? = nil,
         highlight: HighlightColor? = nil,
         verticalAlign: VerticalAlign? = nil) {
        self.bold = bold
        self.italic = italic
        self.underline = underline
        self.strikethrough = strikethrough
        self.fontSize = fontSize
        self.fontName = fontName
        self.color = color
        self.highlight = highlight
        self.verticalAlign = verticalAlign
    }

    /// 合併格式（覆蓋非 nil 值）
    mutating func merge(with other: RunProperties) {
        if other.bold { self.bold = true }
        if other.italic { self.italic = true }
        if let underline = other.underline { self.underline = underline }
        if other.strikethrough { self.strikethrough = true }
        if let fontSize = other.fontSize { self.fontSize = fontSize }
        if let fontName = other.fontName { self.fontName = fontName }
        if let color = other.color { self.color = color }
        if let highlight = other.highlight { self.highlight = highlight }
        if let verticalAlign = other.verticalAlign { self.verticalAlign = verticalAlign }
        if let characterSpacing = other.characterSpacing { self.characterSpacing = characterSpacing }
        if let textEffect = other.textEffect { self.textEffect = textEffect }
        if let rawXML = other.rawXML { self.rawXML = rawXML }
    }
}

// MARK: - Enums

/// 底線類型
enum UnderlineType: String, Codable {
    case single = "single"
    case double = "double"
    case dotted = "dotted"
    case dashed = "dash"
    case wave = "wave"
    case thick = "thick"
    case words = "words"        // 只在文字下，空格無底線
}

/// 螢光標記顏色
enum HighlightColor: String, Codable {
    case yellow = "yellow"
    case green = "green"
    case cyan = "cyan"
    case magenta = "magenta"
    case blue = "blue"
    case red = "red"
    case darkBlue = "darkBlue"
    case darkCyan = "darkCyan"
    case darkGreen = "darkGreen"
    case darkMagenta = "darkMagenta"
    case darkRed = "darkRed"
    case darkYellow = "darkYellow"
    case lightGray = "lightGray"
    case darkGray = "darkGray"
    case black = "black"
    case white = "white"
}

/// 垂直對齊（上標/下標）
enum VerticalAlign: String, Codable {
    case superscript = "superscript"
    case `subscript` = "subscript"
