/// Protocol for streaming output destinations.
///
/// Conforming types can receive streaming text output, enabling
/// memory-efficient document conversion without building intermediate ASTs.
public protocol StreamingOutput {
    /// Write text without newline
    mutating func write(_ text: String) throws

    /// Write text followed by newline
    mutating func writeLine(_ text: String) throws

    /// Write a blank line (for paragraph separation)
    mutating func writeBlankLine() throws

    /// Flush any buffered content
    mutating func flush() throws
}

// MARK: - Default Implementations

public extension StreamingOutput {
    mutating func writeLine(_ text: String) throws {
        try write(text)
        try write("\n")
    }

    mutating func writeBlankLine() throws {
        try write("\n")
    }

    mutating func flush() throws {
        // Default: no-op
    }
}

// MARK: - Built-in Output Types

/// Simple string accumulator for testing or in-memory conversion
public struct StringOutput: StreamingOutput {
    public private(set) var content: String = ""

    public init() {}

    public mutating func write(_ text: String) throws {
        content += text
    }
}

/// File handle output for writing directly to files or stdout
public struct FileHandleOutput: StreamingOutput {
    private let handle: FileHandle

    public init(handle: FileHandle) {
        self.handle = handle
    }

    public static var stdout: FileHandleOutput {
        FileHandleOutput(handle: .standardOutput)
    }

    public mutating func write(_ text: String) throws {
        guard let data = text.data(using: .utf8) else { return }
        try handle.write(contentsOf: data)
    }

    public mutating func flush() throws {
        try handle.synchronize()
    }
}

