    private var output: Output

    /// Track if we need a blank line before the next block
    private var needsBlankLine = false

    /// Current list context for proper indentation
    private var listDepth = 0

    public init(output: Output) {
        self.output = output
    }

    // MARK: - Block Elements

    /// Write a heading (ATX style)
    /// - Parameters:
    ///   - text: The heading text
    ///   - level: Heading level (1-6, will be clamped)
    public mutating func heading(_ text: String, level: Int) throws {
        try ensureBlankLine()
        let clampedLevel = min(max(level, 1), 6)
        let prefix = String(repeating: "#", count: clampedLevel)
        try output.writeLine("\(prefix) \(text)")
        needsBlankLine = true
    }

    /// Write a paragraph
    /// - Parameter text: The paragraph text (will be escaped)
    public mutating func paragraph(_ text: String) throws {
        try ensureBlankLine()
        let escaped = MarkdownEscaping.escape(text, context: .paragraph)
        try output.writeLine(escaped)
        needsBlankLine = true
    }

    /// Write raw text without escaping (use with caution)
    /// - Parameter text: Raw Markdown text
    public mutating func raw(_ text: String) throws {
        try ensureBlankLine()
        try output.writeLine(text)
        needsBlankLine = true
    }

    /// Write a bullet list item
    /// - Parameters:
    ///   - text: The item text
    ///   - level: Nesting level (0 = top level)
    public mutating func bulletItem(_ text: String, level: Int = 0) throws {
        // Only add blank line before first list item
        if listDepth == 0 && level == 0 {
            try ensureBlankLine()
        }

        let indent = String(repeating: "  ", count: level)
        let escaped = MarkdownEscaping.escape(text, context: .paragraph)
        try output.writeLine("\(indent)- \(escaped)")
        listDepth = level + 1
        needsBlankLine = false
    }

    /// Write a numbered list item
    /// - Parameters:
    ///   - text: The item text
    ///   - level: Nesting level (0 = top level)
    ///   - number: The item number (default 1, Markdown auto-increments)
    public mutating func numberedItem(_ text: String, level: Int = 0, number: Int = 1) throws {
        if listDepth == 0 && level == 0 {
            try ensureBlankLine()
        }

        let indent = String(repeating: "  ", count: level)
        let escaped = MarkdownEscaping.escape(text, context: .paragraph)
        try output.writeLine("\(indent)\(number). \(escaped)")
        listDepth = level + 1
        needsBlankLine = false
    }

    /// End the current list (adds blank line after)
    public mutating func endList() throws {
        listDepth = 0
        needsBlankLine = true
    }

    /// Write a code block
    /// - Parameters:
    ///   - code: The code content
    ///   - language: Optional language identifier for syntax highlighting
    public mutating func codeBlock(_ code: String, language: String? = nil) throws {
        try ensureBlankLine()

        let lang = language ?? ""
        try output.writeLine("```\(lang)")
        try output.writeLine(code)
        try output.writeLine("```")

        needsBlankLine = true
    }

    /// Write a blockquote
    /// - Parameter text: The quoted text
    public mutating func blockquote(_ text: String) throws {
        try ensureBlankLine()

        // Handle multi-line quotes
        let lines = text.components(separatedBy: "\n")
        for line in lines {
            try output.writeLine("> \(line)")
        }

        needsBlankLine = true
    }

    /// Write a horizontal rule
    public mutating func horizontalRule() throws {
        try ensureBlankLine()
        try output.writeLine("---")
        needsBlankLine = true
    }

    /// Write a table
    /// - Parameters:
    ///   - headers: Column headers
    ///   - rows: Table rows (each row is an array of cell values)
    ///   - alignment: Optional column alignments
    public mutating func table(
        headers: [String],
        rows: [[String]],
        alignment: [TableAlignment]? = nil
    ) throws {
        try ensureBlankLine()

        // Header row
        let escapedHeaders = headers.map { MarkdownEscaping.escape($0, context: .tableCell) }
        try output.writeLine("| \(escapedHeaders.joined(separator: " | ")) |")

        // Separator row
        let separators = headers.enumerated().map { index, _ in
            separatorCell(for: alignment?[safe: index] ?? .none)
        }
        try output.writeLine("|\(separators.joined(separator: "|"))|")

        // Data rows
        for row in rows {
            let escapedCells = row.map { MarkdownEscaping.escape($0, context: .tableCell) }
            // Pad if row has fewer cells than headers
            let paddedCells = escapedCells + Array(repeating: "", count: max(0, headers.count - escapedCells.count))
            try output.writeLine("| \(paddedCells.prefix(headers.count).joined(separator: " | ")) |")
        }

        needsBlankLine = true
    }

    /// Write a footnote definition
    /// - Parameters:
    ///   - id: Footnote identifier
    ///   - text: Footnote content
    public mutating func footnote(id: String, text: String) throws {
        try ensureBlankLine()
        try output.writeLine("[^\(id)]: \(text)")
        needsBlankLine = true
    }

    // MARK: - Flush

    /// Flush any buffered content to the output
    public mutating func flush() throws {
        try output.flush()
    }

    /// Get the underlying output (for reading accumulated content in StringOutput)
    public func getOutput() -> Output {
        output
    }

    // MARK: - Private Helpers

    private mutating func ensureBlankLine() throws {
        if needsBlankLine {
            try output.writeBlankLine()
            needsBlankLine = false
        }
    }

    private func separatorCell(for alignment: TableAlignment) -> String {
        switch alignment {
        case .none:
            return "---"
        case .left:
            return ":--"
        case .center:
            return ":-:"
        case .right:
            return "--:"
        }
    }
}

// MARK: - Table Alignment

/// Column alignment for Markdown tables
public enum TableAlignment {
    case none
    case left
    case center
    case right
}

// MARK: - Array Safe Subscript

private extension Array {
    subscript(safe index: Int) -> Element? {
        guard index >= 0 && index < count else { return nil }
        return self[index]
    }
}

