import XCTest
@testable import MarkdownSwift

final class EscapingTests: XCTestCase {
    // MARK: - Paragraph Escaping

    func testEscapeBackslash() {
        let result = MarkdownEscaping.escape("path\\to\\file", context: .paragraph)
        XCTAssertEqual(result, "path\\\\to\\\\file")
    }

    func testEscapeAsterisks() {
        let result = MarkdownEscaping.escape("**bold** and *italic*", context: .paragraph)
        XCTAssertEqual(result, "\\*\\*bold\\*\\* and \\*italic\\*")
    }

    func testEscapeUnderscores() {
        let result = MarkdownEscaping.escape("_italic_ and __bold__", context: .paragraph)
        XCTAssertEqual(result, "\\_italic\\_ and \\_\\_bold\\_\\_")
    }

    func testEscapeBackticks() {
        let result = MarkdownEscaping.escape("use `code` here", context: .paragraph)
        XCTAssertEqual(result, "use \\`code\\` here")
    }

    func testEscapeBrackets() {
        let result = MarkdownEscaping.escape("[link](url)", context: .paragraph)
        XCTAssertEqual(result, "\\[link\\](url)")
    }

    func testEscapeHash() {
        let result = MarkdownEscaping.escape("# not a heading", context: .paragraph)
        XCTAssertEqual(result, "\\# not a heading")
    }

    func testEscapeAngleBrackets() {
        let result = MarkdownEscaping.escape("<html> tag", context: .paragraph)
        XCTAssertEqual(result, "\\<html\\> tag")
    }

    func testNoEscapeInRaw() {
        let result = MarkdownEscaping.escape("**bold** _italic_", context: .raw)
        XCTAssertEqual(result, "**bold** _italic_")
    }

    // MARK: - Table Cell Escaping

    func testEscapePipeInTableCell() {
        let result = MarkdownEscaping.escape("A | B", context: .tableCell)
        XCTAssertEqual(result, "A \\| B")
    }

    func testTableCellAlsoEscapesParagraphChars() {
        let result = MarkdownEscaping.escape("*bold* | cell", context: .tableCell)
        XCTAssertEqual(result, "\\*bold\\* \\| cell")
    }

    func testTableCellReplacesNewlines() {
        let result = MarkdownEscaping.escape("line1\nline2", context: .tableCell)
        XCTAssertEqual(result, "line1 line2")
    }

    // MARK: - URL Escaping

    func testEscapeSpaceInURL() {
        let result = MarkdownEscaping.escape("path/to/file name.txt", context: .url)
        XCTAssertTrue(result.contains("%20") || !result.contains(" "))
    }

    // MARK: - String Extension

    func testStringExtension() {
        let text = "**bold**"
        XCTAssertEqual(text.escapedForMarkdown(), "\\*\\*bold\\*\\*")
        XCTAssertEqual(text.escapedForMarkdown(context: .raw), "**bold**")
    }
}

