import XCTest
@testable import MarkdownSwift

final class InlineFormattingTests: XCTestCase {
    // MARK: - Text Formatting

    func testBold() {
        XCTAssertEqual(MarkdownInline.bold("text"), "**text**")
    }

    func testBoldEmpty() {
        XCTAssertEqual(MarkdownInline.bold(""), "")
    }

    func testItalic() {
        XCTAssertEqual(MarkdownInline.italic("text"), "_text_")
    }

    func testItalicEmpty() {
        XCTAssertEqual(MarkdownInline.italic(""), "")
    }

    func testBoldItalic() {
        XCTAssertEqual(MarkdownInline.boldItalic("text"), "***text***")
    }

    func testStrikethrough() {
        XCTAssertEqual(MarkdownInline.strikethrough("text"), "~~text~~")
    }

    // MARK: - Code Spans

    func testCodeSimple() {
        XCTAssertEqual(MarkdownInline.code("let x = 1"), "`let x = 1`")
    }

    func testCodeWithBacktick() {
        // Text containing one backtick should be wrapped with two
        let result = MarkdownInline.code("use `code` here")
        XCTAssertTrue(result.hasPrefix("``"))
        XCTAssertTrue(result.hasSuffix("``"))
    }

    func testCodeWithMultipleBackticks() {
        // Text containing `` should be wrapped with ```
        let result = MarkdownInline.code("text with `` double")
        XCTAssertTrue(result.hasPrefix("```"))
        XCTAssertTrue(result.hasSuffix("```"))
    }

    func testCodeStartingWithBacktick() {
        // Should add space padding
        let result = MarkdownInline.code("`start")
        XCTAssertTrue(result.contains(" `start "))
    }

    // MARK: - Links

    func testLink() {
        let result = MarkdownInline.link("Click here", url: "https://example.com")
        XCTAssertEqual(result, "[Click here](https://example.com)")
    }

    func testLinkWithTitle() {
        let result = MarkdownInline.link("Click", url: "https://example.com", title: "Title")
        XCTAssertEqual(result, "[Click](https://example.com \"Title\")")
    }

    func testLinkWithSpecialChars() {
        let result = MarkdownInline.link("Click [here]", url: "https://example.com")
        XCTAssertTrue(result.contains("\\[here\\]"))
    }

    // MARK: - Images

    func testImage() {
        let result = MarkdownInline.image("Alt text", url: "image.png")
        XCTAssertEqual(result, "![Alt text](image.png)")
    }

    func testImageWithTitle() {
        let result = MarkdownInline.image("Alt", url: "img.png", title: "Description")
        XCTAssertEqual(result, "![Alt](img.png \"Description\")")
    }

    // MARK: - Footnotes

    func testFootnoteRef() {
        XCTAssertEqual(MarkdownInline.footnoteRef("1"), "[^1]")
        XCTAssertEqual(MarkdownInline.footnoteRef("note"), "[^note]")
    }
}

