    func testParagraph() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.paragraph("Hello world")
        XCTAssertEqual(writer.getOutput().content, "Hello world\n")
    }

    func testParagraphEscapesSpecialChars() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.paragraph("Use *asterisks* carefully")
        XCTAssertTrue(writer.getOutput().content.contains("\\*"))
    }

