        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.heading("Title", level: 1)
        try writer.paragraph("Content")
        let result = writer.getOutput().content
        // Should have blank line between heading and paragraph
        XCTAssertTrue(result.contains("\n\n"))
    }

