import Foundation

/// Context for escaping text in Markdown
public enum EscapeContext {
    /// General paragraph text: escape * _ ` [ ] # < >
    case paragraph

    /// Table cell: additionally escape |
    case tableCell

    /// Inside inline code span: escape ` only
    case codeSpan

    /// URL context: encode spaces and special characters
    case url

    /// No escaping
    case raw
}

/// Markdown text escaping utilities
public enum MarkdownEscaping {
    // MARK: - Character Sets

    /// Characters that need escaping in paragraph context
    private static let paragraphEscapeChars: Set<Character> = [
        "\\", "*", "_", "`", "[", "]", "#", "<", ">"
    ]

    /// Additional characters to escape in table cells
    private static let tableCellExtraChars: Set<Character> = ["|"]

    // MARK: - Public API

    /// Escape text according to the given context
    /// - Parameters:
    ///   - text: The text to escape
    ///   - context: The context determining which characters to escape
    /// - Returns: Escaped text safe for the given context
    public static func escape(_ text: String, context: EscapeContext) -> String {
        switch context {
        case .raw:
            return text

        case .paragraph:
            return escapeParagraph(text)

        case .tableCell:
            return escapeTableCell(text)

        case .codeSpan:
            return escapeCodeSpan(text)

        case .url:
            return escapeURL(text)
        }
    }

    // MARK: - Private Implementation

    private static func escapeParagraph(_ text: String) -> String {
        var result = ""
        result.reserveCapacity(text.count + text.count / 10) // Reserve extra for escapes

        for char in text {
            if paragraphEscapeChars.contains(char) {
                result.append("\\")
            }
            result.append(char)
        }

        return result
    }

    private static func escapeTableCell(_ text: String) -> String {
        var result = ""
        result.reserveCapacity(text.count + text.count / 10)

        let allEscapeChars = paragraphEscapeChars.union(tableCellExtraChars)

        for char in text {
            if allEscapeChars.contains(char) {
                result.append("\\")
            }
            result.append(char)
        }

        // Also replace newlines with space (tables can't have line breaks in cells)
        return result.replacingOccurrences(of: "\n", with: " ")
    }

    private static func escapeCodeSpan(_ text: String) -> String {
        // For code spans, we need to handle backticks specially
        // If text contains backticks, we might need to use more backticks for the fence
        text.replacingOccurrences(of: "`", with: "\\`")
    }

    private static func escapeURL(_ text: String) -> String {
        // URL encode spaces and parentheses
        text.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? text
    }
}

// MARK: - Convenience Extension

public extension String {
    /// Escape this string for Markdown
    /// - Parameter context: The escaping context
    /// - Returns: Escaped string
    func escapedForMarkdown(context: EscapeContext = .paragraph) -> String {
        MarkdownEscaping.escape(self, context: context)
    }
}

