/// Write a heading (Setext style) - only supports level 1 and 2
/// - Parameters:
///   - text: The heading text
///   - level: Heading level (1 or 2, others will use ATX)
public mutating func setextHeading(_ text: String, level: Int) throws {
    guard level == 1 || level == 2 else {
        // Fall back to ATX for other levels
        try heading(text, level: level)
        return
    }

    try ensureBlankLine()
    try output.writeLine(text)
    let underline = level == 1 ? "=" : "-"
    try output.writeLine(String(repeating: underline, count: max(text.count, 3)))
    needsBlankLine = true
}

