import Foundation

/// Inline Markdown formatting utilities
///
/// These are pure functions that return formatted strings.
/// They don't write to output directly, following the functional correspondence principle:
/// `f: Element → String`
public enum MarkdownInline {
    // MARK: - Text Formatting

    /// Format text as bold: **text**
    public static func bold(_ text: String) -> String {
        guard !text.isEmpty else { return "" }
        return "**\(text)**"
    }

    /// Format text as italic: _text_
    public static func italic(_ text: String) -> String {
        guard !text.isEmpty else { return "" }
        return "_\(text)_"
    }

    /// Format text as bold and italic: ***text***
    public static func boldItalic(_ text: String) -> String {
        guard !text.isEmpty else { return "" }
        return "***\(text)***"
    }

    /// Format text as strikethrough: ~~text~~
    public static func strikethrough(_ text: String) -> String {
        guard !text.isEmpty else { return "" }
        return "~~\(text)~~"
    }

    /// Format text as inline code: `code`
    ///
    /// Automatically handles text containing backticks by using appropriate fence length
    public static func code(_ text: String) -> String {
        guard !text.isEmpty else { return "" }

