        let escapedText = MarkdownEscaping.escape(text, context: .paragraph)
        let escapedURL = MarkdownEscaping.escape(url, context: .url)

        if let title = title, !title.isEmpty {
            let escapedTitle = title.replacingOccurrences(of: "\"", with: "\\\"")
            return "[\(escapedText)](\(escapedURL) \"\(escapedTitle)\")"
        } else {
            return "[\(escapedText)](\(escapedURL))"
        }
    }

    /// Format an image: ![alt](url)
    public static func image(_ alt: String, url: String) -> String {
        let escapedAlt = MarkdownEscaping.escape(alt, context: .paragraph)
        let escapedURL = MarkdownEscaping.escape(url, context: .url)
        return "![\(escapedAlt)](\(escapedURL))"
    }

    /// Format an image with optional title: ![alt](url "title")
    public static func image(_ alt: String, url: String, title: String?) -> String {
        let escapedAlt = MarkdownEscaping.escape(alt, context: .paragraph)
        let escapedURL = MarkdownEscaping.escape(url, context: .url)

        if let title = title, !title.isEmpty {
            let escapedTitle = title.replacingOccurrences(of: "\"", with: "\\\"")
            return "![\(escapedAlt)](\(escapedURL) \"\(escapedTitle)\")"
        } else {
            return "![\(escapedAlt)](\(escapedURL))"
        }
    }

    // MARK: - Footnotes

    /// Format a footnote reference: [^id]
    public static func footnoteRef(_ id: String) -> String {
        "[^\(id)]"
    }

    // MARK: - Autolinks

    /// Format an autolink: <url>
    /// CommonMark 6.7: Autolinks are absolute URIs and email addresses inside < and >
    public static func autolink(_ url: String) -> String {
        "<\(url)>"
    }

    /// Format an email autolink: <email@example.com>
    public static func emailAutolink(_ email: String) -> String {
        "<\(email)>"
    }

    // MARK: - Line Breaks

    /// Format a hard line break (trailing two spaces)
    /// CommonMark 6.9: A line ending preceded by two or more spaces
    public static func hardBreak() -> String {
        "  \n"
    }

    /// Format a hard line break using backslash
    /// CommonMark 6.9: A backslash before the line ending
    public static func hardBreakBackslash() -> String {
        "\\\n"
    }

    // MARK: - HTML Entities

    /// Format an HTML entity reference
    /// CommonMark 6.2: Entity and numeric character references
    public static func htmlEntity(_ name: String) -> String {
        "&\(name);"
    }

    /// Common HTML entities for convenience
    public enum HTMLEntity {
        public static let amp = "&amp;"
        public static let lt = "&lt;"
        public static let gt = "&gt;"
        public static let quot = "&quot;"
        public static let apos = "&apos;"
        public static let nbsp = "&nbsp;"
        public static let copy = "&copy;"
        public static let reg = "&reg;"
        public static let trade = "&trade;"
    }

    // MARK: - Raw HTML

    /// Embed raw HTML inline (use with caution)
    /// CommonMark 6.8: Raw HTML
    public static func rawHTML(_ html: String) -> String {
        html
    }

    // MARK: - Reference Links

    /// Format a reference-style link: [text][ref]
    public static func linkRef(_ text: String, ref: String) -> String {
        let escapedText = MarkdownEscaping.escape(text, context: .paragraph)
        "[\(escapedText)][\(ref)]"
    }

    /// Format a collapsed reference link: [ref][]
    public static func linkRefCollapsed(_ ref: String) -> String {
        "[\(ref)][]"
    }

    /// Format a shortcut reference link: [ref]
    public static func linkRefShortcut(_ ref: String) -> String {
        "[\(ref)]"
    }

    // MARK: - Private Helpers

    private static func countMaxConsecutiveBackticks(_ text: String) -> Int {
        var maxCount = 0
        var currentCount = 0

        for char in text {
            if char == "`" {
                currentCount += 1
                maxCount = max(maxCount, currentCount)
            } else {
                currentCount = 0
            }
        }

        return maxCount
    }
}

