import XCTest
@testable import MarkdownSwift

final class MarkdownWriterTests: XCTestCase {
    // MARK: - Headings

    func testHeading1() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.heading("Title", level: 1)
        XCTAssertEqual(writer.getOutput().content, "# Title\n")
    }

    func testHeading2() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.heading("Subtitle", level: 2)
        XCTAssertEqual(writer.getOutput().content, "## Subtitle\n")
    }

    func testHeadingLevelClamped() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.heading("Deep", level: 10)
        // Should be clamped to 6
        XCTAssertTrue(writer.getOutput().content.hasPrefix("######"))
    }

    // MARK: - Paragraphs

    func testParagraph() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.paragraph("Hello world")
        XCTAssertEqual(writer.getOutput().content, "Hello world\n")
    }

    func testParagraphEscapesSpecialChars() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.paragraph("Use *asterisks* carefully")
        XCTAssertTrue(writer.getOutput().content.contains("\\*"))
    }

    // MARK: - Block Separation

    func testBlankLineBetweenBlocks() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.heading("Title", level: 1)
        try writer.paragraph("Content")
        let result = writer.getOutput().content
        // Should have blank line between heading and paragraph
        XCTAssertTrue(result.contains("\n\n"))
    }

    // MARK: - Lists

    func testBulletList() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.bulletItem("Item 1")
        try writer.bulletItem("Item 2")
        try writer.bulletItem("Item 3")
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("- Item 1"))
        XCTAssertTrue(result.contains("- Item 2"))
        XCTAssertTrue(result.contains("- Item 3"))
    }

    func testNestedBulletList() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.bulletItem("Parent", level: 0)
        try writer.bulletItem("Child", level: 1)
        try writer.bulletItem("Grandchild", level: 2)
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("- Parent"))
        XCTAssertTrue(result.contains("  - Child"))
        XCTAssertTrue(result.contains("    - Grandchild"))
    }

    func testNumberedList() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.numberedItem("First")
        try writer.numberedItem("Second")
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("1. First"))
        XCTAssertTrue(result.contains("1. Second"))
    }

    // MARK: - Code Blocks

    func testCodeBlock() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.codeBlock("let x = 1")
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("```"))
        XCTAssertTrue(result.contains("let x = 1"))
    }

    func testCodeBlockWithLanguage() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.codeBlock("let x = 1", language: "swift")
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("```swift"))
    }

    // MARK: - Blockquotes

    func testBlockquote() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.blockquote("Quoted text")
        XCTAssertTrue(writer.getOutput().content.contains("> Quoted text"))
    }

    func testMultilineBlockquote() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.blockquote("Line 1\nLine 2")
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("> Line 1"))
        XCTAssertTrue(result.contains("> Line 2"))
    }

    // MARK: - Horizontal Rule

    func testHorizontalRule() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.horizontalRule()
        XCTAssertTrue(writer.getOutput().content.contains("---"))
    }

    // MARK: - Tables

    func testSimpleTable() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.table(
            headers: ["Name", "Age"],
            rows: [
                ["Alice", "30"],
                ["Bob", "25"]
            ]
        )
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("| Name | Age |"))
        XCTAssertTrue(result.contains("|---|---|"))
        XCTAssertTrue(result.contains("| Alice | 30 |"))
        XCTAssertTrue(result.contains("| Bob | 25 |"))
    }

    func testTableWithAlignment() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.table(
            headers: ["Left", "Center", "Right"],
            rows: [["A", "B", "C"]],
            alignment: [.left, .center, .right]
        )
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains(":--"))
        XCTAssertTrue(result.contains(":-:"))
        XCTAssertTrue(result.contains("--:"))
    }

    func testTableEscapesPipe() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.table(
            headers: ["A | B"],
            rows: [["X | Y"]]
        )
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("\\|"))
    }

    // MARK: - Footnotes

    func testFootnote() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.footnote(id: "1", text: "This is a footnote")
        XCTAssertTrue(writer.getOutput().content.contains("[^1]: This is a footnote"))
    }

    // MARK: - Full Document

    func testFullDocument() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)

        try writer.heading("My Document", level: 1)
        try writer.paragraph("This is the introduction.")
        try writer.heading("Section 1", level: 2)
        try writer.bulletItem("Point A")
        try writer.bulletItem("Point B")
        try writer.endList()
        try writer.codeBlock("print(\"Hello\")", language: "python")

        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("# My Document"))
        XCTAssertTrue(result.contains("## Section 1"))
        XCTAssertTrue(result.contains("- Point A"))
        XCTAssertTrue(result.contains("```python"))
    }
}

