    func testHeadingLevelClamped() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.heading("Deep", level: 10)
        // Should be clamped to 6
        XCTAssertTrue(writer.getOutput().content.hasPrefix("######"))
    }

