    func testNestedBulletList() throws {
        var output = StringOutput()
        var writer = MarkdownWriter(output: output)
        try writer.bulletItem("Parent", level: 0)
        try writer.bulletItem("Child", level: 1)
        try writer.bulletItem("Grandchild", level: 2)
        let result = writer.getOutput().content
        XCTAssertTrue(result.contains("- Parent"))
        XCTAssertTrue(result.contains("  - Child"))
        XCTAssertTrue(result.contains("    - Grandchild"))
