///
/// ```swift
/// let writer = try MarkerWriter(
///     outputDirectory: URL(fileURLWithPath: "output/"),
///     filename: "document",
///     classifier: PassthroughClassifier()
/// )
///
/// // Write content
/// try writer.heading("Title", level: 1)
/// try writer.paragraph("Some text")
