   414→            guard let typeStr = element.attribute(forName: "w:type")?.stringValue,
   415→                  let type = StyleType(rawValue: typeStr) else { continue }
   416→
   417→            var name = styleId
   418→            if let nameElement = element.elements(forName: "w:name").first,
   419→               let val = nameElement.attribute(forName: "w:val")?.stringValue {
   420→                name = val
   421→            }
   422→
   423→            var style = Style(id: styleId, name: name, type: type)
   424→
   425→            // 基於
   426→            if let basedOn = element.elements(forName: "w:basedOn").first,
   427→               let val = basedOn.attribute(forName: "w:val")?.stringValue {
   428→                style.basedOn = val
   429→            }
   430→
   431→            // 下一樣式
   432→            if let next = element.elements(forName: "w:next").first,
   433→               let val = next.attribute(forName: "w:val")?.stringValue {
   434→                style.nextStyle = val
   435→            }
   436→
   437→            // 預設
   438→            if element.attribute(forName: "w:default")?.stringValue == "1" {
   439→                style.isDefault = true
