   253→        // 解析表格行
   254→        for tr in element.elements(forName: "w:tr") {
   255→            let row = try parseTableRow(from: tr)
   256→            table.rows.append(row)
   257→        }
   258→
   259→        return table
   260→    }
   261→
   262→    private static func parseTableProperties(from element: XMLElement) -> TableProperties {
   263→        var props = TableProperties()
   264→
   265→        // 寬度
   266→        if let tblW = element.elements(forName: "w:tblW").first {
   267→            if let w = tblW.attribute(forName: "w:w")?.stringValue {
   268→                props.width = Int(w)
   269→            }
   270→            if let type = tblW.attribute(forName: "w:type")?.stringValue {
   271→                props.widthType = WidthType(rawValue: type)
   272→            }
   273→        }
   274→
   275→        // 對齊
   276→        if let jc = element.elements(forName: "w:jc").first,
   277→           let val = jc.attribute(forName: "w:val")?.stringValue {
   278→            props.alignment = Alignment(rawValue: val)
   279→        }
   280→
   281→        // 版面配置
   282→        if let layout = element.elements(forName: "w:tblLayout").first,
   283→           let val = layout.attribute(forName: "w:type")?.stringValue {
   284→            props.layout = TableLayout(rawValue: val)
   285→        }
   286→
   287→        return props
   288→    }
   289→
   290→    private static func parseTableRow(from element: XMLElement) throws -> TableRow {
   291→        var row = TableRow()
   292→
   293→        // 解析行屬性
   294→        if let trPr = element.elements(forName: "w:trPr").first {
   295→            row.properties = parseTableRowProperties(from: trPr)
   296→        }
   297→
   298→        // 解析儲存格
   299→        for tc in element.elements(forName: "w:tc") {
   300→            let cell = try parseTableCell(from: tc)
   301→            row.cells.append(cell)
   302→        }
   303→
   304→        return row
   305→    }
   306→
   307→    private static func parseTableRowProperties(from element: XMLElement) -> TableRowProperties {
   308→        var props = TableRowProperties()
   309→
   310→        // 行高
   311→        if let trHeight = element.elements(forName: "w:trHeight").first {
   312→            if let val = trHeight.attribute(forName: "w:val")?.stringValue {
   313→                props.height = Int(val)
   314→            }
   315→            if let hRule = trHeight.attribute(forName: "w:hRule")?.stringValue {
   316→                props.heightRule = HeightRule(rawValue: hRule)
   317→            }
   318→        }
   319→
   320→        // 表頭行
   321→        if element.elements(forName: "w:tblHeader").first != nil {
   322→            props.isHeader = true
   323→        }
   324→
   325→        // 禁止分割
   326→        if element.elements(forName: "w:cantSplit").first != nil {
   327→            props.cantSplit = true
   328→        }
   329→
   330→        return props
   331→    }
   332→
   333→    private static func parseTableCell(from element: XMLElement) throws -> TableCell {
   334→        var cell = TableCell()
   335→        cell.paragraphs = []
   336→
   337→        // 解析儲存格屬性
   338→        if let tcPr = element.elements(forName: "w:tcPr").first {
   339→            cell.properties = parseTableCellProperties(from: tcPr)
   340→        }
   341→
   342→        // 解析段落
   343→        for p in element.elements(forName: "w:p") {
   344→            let para = try parseParagraph(from: p)
   345→            cell.paragraphs.append(para)
   346→        }
   347→
   348→        // 確保至少有一個段落
   349→        if cell.paragraphs.isEmpty {
   350→            cell.paragraphs.append(Paragraph())
   351→        }
   352→
   353→        return cell
   354→    }
