   356→    private static func parseTableCellProperties(from element: XMLElement) -> TableCellProperties {
   357→        var props = TableCellProperties()
   358→
   359→        // 寬度
   360→        if let tcW = element.elements(forName: "w:tcW").first {
   361→            if let w = tcW.attribute(forName: "w:w")?.stringValue {
   362→                props.width = Int(w)
   363→            }
   364→            if let type = tcW.attribute(forName: "w:type")?.stringValue {
   365→                props.widthType = WidthType(rawValue: type)
   366→            }
   367→        }
   368→
   369→        // 水平合併
   370→        if let gridSpan = element.elements(forName: "w:gridSpan").first,
   371→           let val = gridSpan.attribute(forName: "w:val")?.stringValue {
   372→            props.gridSpan = Int(val)
   373→        }
   374→
   375→        // 垂直合併
   376→        if let vMerge = element.elements(forName: "w:vMerge").first,
   377→           let val = vMerge.attribute(forName: "w:val")?.stringValue {
   378→            props.verticalMerge = VerticalMerge(rawValue: val)
   379→        }
   380→
   381→        // 垂直對齊
   382→        if let vAlign = element.elements(forName: "w:vAlign").first,
   383→           let val = vAlign.attribute(forName: "w:val")?.stringValue {
   384→            props.verticalAlignment = CellVerticalAlignment(rawValue: val)
   385→        }
   386→
   387→        // 底色
   388→        if let shd = element.elements(forName: "w:shd").first,
   389→           let fill = shd.attribute(forName: "w:fill")?.stringValue {
   390→            var shading = CellShading(fill: fill)
   391→            if let color = shd.attribute(forName: "w:color")?.stringValue {
   392→                shading.color = color
   393→            }
   394→            if let val = shd.attribute(forName: "w:val")?.stringValue {
   395→                shading.pattern = ShadingPattern(rawValue: val)
   396→            }
   397→            props.shading = shading
   398→        }
   399→
   400→        return props
   401→    }
   402→
   403→    // MARK: - Styles Parsing
   404→
   405→    private static func parseStyles(from xml: XMLDocument) throws -> [Style] {
   406→        var styles: [Style] = []
   407→
   408→        let styleNodes = try xml.nodes(forXPath: "//*[local-name()='style']")
   409→
   410→        for node in styleNodes {
   411→            guard let element = node as? XMLElement else { continue }
   412→
   413→            guard let styleId = element.attribute(forName: "w:styleId")?.stringValue else { continue }
   414→            guard let typeStr = element.attribute(forName: "w:type")?.stringValue,
   415→                  let type = StyleType(rawValue: typeStr) else { continue }
   416→
   417→            var name = styleId
   418→            if let nameElement = element.elements(forName: "w:name").first,
   419→               let val = nameElement.attribute(forName: "w:val")?.stringValue {
   420→                name = val
   421→            }
   422→
   423→            var style = Style(id: styleId, name: name, type: type)
   424→
   425→            // 基於
   426→            if let basedOn = element.elements(forName: "w:basedOn").first,
   427→               let val = basedOn.attribute(forName: "w:val")?.stringValue {
   428→                style.basedOn = val
   429→            }
   430→
   431→            // 下一樣式
   432→            if let next = element.elements(forName: "w:next").first,
   433→               let val = next.attribute(forName: "w:val")?.stringValue {
   434→                style.nextStyle = val
   435→            }
   436→
   437→            // 預設
   438→            if element.attribute(forName: "w:default")?.stringValue == "1" {
   439→                style.isDefault = true
   440→            }
   441→
   442→            // 快速樣式
   443→            style.isQuickStyle = element.elements(forName: "w:qFormat").first != nil
   444→
   445→            // 段落屬性
   446→            if let pPr = element.elements(forName: "w:pPr").first {
   447→                style.paragraphProperties = parseParagraphProperties(from: pPr)
   448→            }
   449→
   450→            // Run 屬性
   451→            if let rPr = element.elements(forName: "w:rPr").first {
   452→                style.runProperties = parseRunProperties(from: rPr)
   453→            }
   454→
   455→            styles.append(style)
   456→        }
   457→
   458→        // 如果沒有讀到樣式，使用預設樣式
   459→        if styles.isEmpty {
   460→            styles = Style.defaultStyles
   461→        }
   462→
   463→        return styles
   464→    }
   465→
   466→    // MARK: - Core Properties Parsing
   467→
   468→    private static func parseCoreProperties(from xml: XMLDocument) throws -> DocumentProperties {
   469→        var props = DocumentProperties()
   470→
   471→        // 標題
   472→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='title']"),
   473→           let node = nodes.first {
   474→            props.title = node.stringValue
   475→        }
   476→
   477→        // 主題
   478→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='subject']"),
   479→           let node = nodes.first {
   480→            props.subject = node.stringValue
   481→        }
   482→
   483→        // 作者
   484→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='creator']"),
   485→           let node = nodes.first {
   486→            props.creator = node.stringValue
   487→        }
   488→
   489→        // 關鍵字
   490→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='keywords']"),
   491→           let node = nodes.first {
   492→            props.keywords = node.stringValue
   493→        }
   494→
   495→        // 描述
   496→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='description']"),
   497→           let node = nodes.first {
   498→            props.description = node.stringValue
   499→        }
   500→
   501→        // 最後修改者
   502→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='lastModifiedBy']"),
   503→           let node = nodes.first {
   504→            props.lastModifiedBy = node.stringValue
   505→        }
   506→
   507→        // 版本
   508→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='revision']"),
   509→           let node = nodes.first,
   510→           let value = node.stringValue {
   511→            props.revision = Int(value)
   512→        }
   513→
   514→        // 建立日期
   515→        let dateFormatter = ISO8601DateFormatter()
   516→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='created']"),
   517→           let node = nodes.first,
   518→           let value = node.stringValue {
   519→            props.created = dateFormatter.date(from: value)
   520→        }
   521→
   522→        // 修改日期
   523→        if let nodes = try? xml.nodes(forXPath: "//*[local-name()='modified']"),
   524→           let node = nodes.first,
   525→           let value = node.stringValue {
   526→            props.modified = dateFormatter.date(from: value)
   527→        }
   528→
   529→        return props
   530→    }
   531→
   532→    // MARK: - Comments Parsing
   533→
   534→    private static func parseComments(from xml: XMLDocument) throws -> CommentsCollection {
   535→        var collection = CommentsCollection()
   536→
   537→        // 取得所有註解節點
   538→        let commentNodes = try xml.nodes(forXPath: "//*[local-name()='comment']")
   539→
   540→        for node in commentNodes {
   541→            guard let element = node as? XMLElement else { continue }
   542→
   543→            // 解析註解 ID
   544→            guard let idStr = element.attribute(forName: "w:id")?.stringValue,
   545→                  let id = Int(idStr) else { continue }
   546→
   547→            // 解析作者
   548→            let author = element.attribute(forName: "w:author")?.stringValue ?? "Unknown"
   549→
   550→            // 解析縮寫
   551→            let initials = element.attribute(forName: "w:initials")?.stringValue
   552→
   553→            // 解析日期
   554→            let dateFormatter = ISO8601DateFormatter()
   555→            var date = Date()
   556→            if let dateStr = element.attribute(forName: "w:date")?.stringValue {
   557→                date = dateFormatter.date(from: dateStr) ?? Date()
   558→            }
   559→
   560→            // 解析註解文字（從 w:p/w:r/w:t 取得）
   561→            var text = ""
   562→            let textNodes = try element.nodes(forXPath: ".//*[local-name()='t']")
   563→            for textNode in textNodes {
   564→                text += textNode.stringValue ?? ""
   565→            }
   566→
   567→            // 建立 Comment 物件
   568→            // 注意：從 comments.xml 讀取時，paragraphIndex 需要從文件中的 commentRangeStart 來確定
   569→            // 這裡先設為 -1，表示需要從文件內容對應
   570→            var comment = Comment(
   571→                id: id,
   572→                author: author,
   573→                text: text.trimmingCharacters(in: .whitespacesAndNewlines),
   574→                paragraphIndex: -1,
   575→                date: date,
   576→                initials: initials
   577→            )
   578→
   579→            // 嘗試解析 w14:paraId（用於回覆連結）
   580→            // 從段落屬性中取得
   581→            if let pElement = element.elements(forName: "w:p").first {
   582→                // w14:paraId 可能在段落屬性中
   583→                if let paraIdAttr = pElement.attribute(forName: "w14:paraId")?.stringValue {
   584→                    comment.paraId = paraIdAttr
   585→                }
   586→            }
   587→
   588→            collection.comments.append(comment)
   589→        }
   590→
   591→        return collection
   592→    }
   593→}
