   310→
   311→            // 移除被合併的儲存格（從後往前移除以保持索引正確）
   312→            for col in (startCol + 1...endCol).reversed() {
   313→                table.rows[row].cells.remove(at: col)
   314→            }
   315→
   316→            body.children[actualIndex] = .table(table)
   317→            if tableIndex < body.tables.count {
   318→                body.tables[tableIndex] = table
