   339→
   340→            // 設定第一個儲存格為 restart
   341→            if col < table.rows[startRow].cells.count {
   342→                table.rows[startRow].cells[col].properties.verticalMerge = .restart
   343→            }
   344→
   345→            // 設定其餘儲存格為 continue
   346→            for row in (startRow + 1)...endRow {
   347→                if col < table.rows[row].cells.count {
   348→                    table.rows[row].cells[col].properties.verticalMerge = .continue
   349→                }
   350→            }
   351→
   352→            body.children[actualIndex] = .table(table)
   353→            if tableIndex < body.tables.count {
   354→                body.tables[tableIndex] = table
   355→            }
   356→        }
   357→    }
