   359→    /// 設定表格樣式（邊框）
   360→    public mutating func setTableBorders(tableIndex: Int, borders: TableBorders) throws {
   361→        let tableIndices = getTableIndices()
   362→
   363→        guard tableIndex >= 0 && tableIndex < tableIndices.count else {
