   422→
   423→    /// 更新樣式
   424→    public mutating func updateStyle(id: String, with updates: StyleUpdate) throws {
   425→        guard let index = styles.firstIndex(where: { $0.id == id }) else {
   426→            throw WordError.invalidFormat("Style '\(id)' not found")
   427→        }
   428→
   429→        var style = styles[index]
   430→
   431→        if let name = updates.name {
   432→            style.name = name
   433→        }
   434→        if let basedOn = updates.basedOn {
   435→            style.basedOn = basedOn
   436→        }
   437→        if let nextStyle = updates.nextStyle {
   438→            style.nextStyle = nextStyle
   439→        }
   440→        if let isQuickStyle = updates.isQuickStyle {
   441→            style.isQuickStyle = isQuickStyle
   442→        }
   443→        if let paragraphProps = updates.paragraphProperties {
   444→            if style.paragraphProperties == nil {
   445→                style.paragraphProperties = ParagraphProperties()
   446→            }
   447→            style.paragraphProperties?.merge(with: paragraphProps)
   448→        }
   449→        if let runProps = updates.runProperties {
   450→            if style.runProperties == nil {
   451→                style.runProperties = RunProperties()
   452→            }
   453→            style.runProperties?.merge(with: runProps)
   454→        }
   455→
   456→        styles[index] = style
   457→    }
