   830→    /// 更新圖片大小
   831→    public mutating func updateImage(imageId: String, widthPx: Int? = nil, heightPx: Int? = nil) throws {
   832→        // 搜尋所有段落找到含有此圖片的 Run
   833→        for i in 0..<body.children.count {
   834→            if case .paragraph(var para) = body.children[i] {
   835→                for j in 0..<para.runs.count {
   836→                    if var drawing = para.runs[j].drawing, drawing.imageId == imageId {
   837→                        if let w = widthPx {
   838→                            drawing.width = w * 9525  // 轉換為 EMU
   839→                        }
   840→                        if let h = heightPx {
   841→                            drawing.height = h * 9525
   842→                        }
   843→                        para.runs[j].drawing = drawing
   844→                        body.children[i] = .paragraph(para)
   845→                        return
   846→                    }
   847→                }
   848→            }
   849→        }
   850→        throw WordError.invalidFormat("Image '\(imageId)' not found")
   851→    }
