   920→                            heightPx = drawing.heightInPixels
   921→                            break
   922→                        }
   923→                    }
   924→                }
   925→            }
   926→
   927→            result.append((id: image.id, fileName: image.fileName, widthPx: widthPx, heightPx: heightPx))
