  1101→    /// 插入書籤
  1102→    public mutating func insertBookmark(
  1103→        name: String,
  1104→        at paragraphIndex: Int? = nil
  1105→    ) throws -> Int {
  1106→        // 驗證書籤名稱
  1107→        let normalizedName = Bookmark.normalizeName(name)
  1108→        guard Bookmark.validateName(normalizedName) else {
  1109→            throw BookmarkError.invalidName(name)
  1110→        }
  1111→
  1112→        // 檢查是否已存在同名書籤
  1113→        for child in body.children {
  1114→            if case .paragraph(let para) = child {
  1115→                if para.bookmarks.contains(where: { $0.name == normalizedName }) {
  1116→                    throw BookmarkError.duplicateName(normalizedName)
  1117→                }
  1118→            }
  1119→        }
  1120→
  1121→        let bookmarkId = nextBookmarkId
  1122→        nextBookmarkId += 1
  1123→
  1124→        let bookmark = Bookmark(id: bookmarkId, name: normalizedName)
  1125→
  1126→        if let index = paragraphIndex {
  1127→            let paragraphIndices = body.children.enumerated().compactMap { (i, child) -> Int? in
  1128→                if case .paragraph = child { return i }
  1129→                return nil
  1130→            }
  1131→
  1132→            guard index >= 0 && index < paragraphIndices.count else {
  1133→                throw WordError.invalidIndex(index)
  1134→            }
  1135→
  1136→            let actualIndex = paragraphIndices[index]
  1137→            if case .paragraph(var para) = body.children[actualIndex] {
  1138→                para.bookmarks.append(bookmark)
  1139→                body.children[actualIndex] = .paragraph(para)
  1140→            }
  1141→        } else {
  1142→            // 加到最後一個段落，如果沒有段落則建立新的
  1143→            if let lastIndex = body.children.lastIndex(where: {
  1144→                if case .paragraph = $0 { return true }
  1145→                return false
  1146→            }) {
  1147→                if case .paragraph(var para) = body.children[lastIndex] {
  1148→                    para.bookmarks.append(bookmark)
  1149→                    body.children[lastIndex] = .paragraph(para)
  1150→                }
  1151→            } else {
  1152→                var para = Paragraph()
  1153→                para.bookmarks.append(bookmark)
  1154→                appendParagraph(para)
  1155→            }
  1156→        }
  1157→
  1158→        return bookmarkId
  1159→    }
  1160→
  1161→    /// 刪除書籤
  1162→    public mutating func deleteBookmark(name: String) throws {
  1163→        for i in 0..<body.children.count {
  1164→            if case .paragraph(var para) = body.children[i] {
  1165→                if let index = para.bookmarks.firstIndex(where: { $0.name == name }) {
