  1297→    /// 接受修訂
  1298→    public mutating func acceptRevision(revisionId: Int) throws {
  1299→        guard let index = revisions.revisions.firstIndex(where: { $0.id == revisionId }) else {
  1300→            throw RevisionError.notFound(revisionId)
  1301→        }
  1302→
  1303→        let revision = revisions.revisions[index]
  1304→
  1305→        // 根據修訂類型處理
  1306→        switch revision.type {
  1307→        case .insertion:
  1308→            // 接受插入：移除標記，保留文字（文字已在文件中）
  1309→            break
  1310→        case .deletion:
  1311→            // 接受刪除：實際移除被標記為刪除的文字
  1312→            let paragraphIndices = body.children.enumerated().compactMap { (i, child) -> Int? in
  1313→                if case .paragraph = child { return i }
  1314→                return nil
  1315→            }
  1316→
  1317→            if revision.paragraphIndex >= 0 && revision.paragraphIndex < paragraphIndices.count {
  1318→                let actualIndex = paragraphIndices[revision.paragraphIndex]
  1319→                if case .paragraph(var para) = body.children[actualIndex] {
  1320→                    // 移除被刪除的文字
  1321→                    if let originalText = revision.originalText {
  1322→                        for j in 0..<para.runs.count {
  1323→                            para.runs[j].text = para.runs[j].text.replacingOccurrences(of: originalText, with: "")
  1324→                        }
  1325→                    }
  1326→                    body.children[actualIndex] = .paragraph(para)
  1327→                }
  1328→            }
  1329→        case .formatting, .paragraphChange, .formatChange:
  1330→            // 接受格式變更：保留新格式
  1331→            break
  1332→        case .moveFrom, .moveTo:
  1333→            // 接受移動：保留目標位置的文字
  1334→            break
  1335→        }
  1336→
  1337→        // 移除修訂記錄
  1338→        revisions.revisions.remove(at: index)
  1339→    }
  1340→
  1341→    /// 拒絕修訂
  1342→    public mutating func rejectRevision(revisionId: Int) throws {
  1343→        guard let index = revisions.revisions.firstIndex(where: { $0.id == revisionId }) else {
  1344→            throw RevisionError.notFound(revisionId)
  1345→        }
  1346→
  1347→        let revision = revisions.revisions[index]
  1348→
  1349→        // 根據修訂類型處理
  1350→        switch revision.type {
  1351→        case .insertion:
  1352→            // 拒絕插入：移除插入的文字
  1353→            let paragraphIndices = body.children.enumerated().compactMap { (i, child) -> Int? in
  1354→                if case .paragraph = child { return i }
  1355→                return nil
  1356→            }
  1357→
  1358→            if revision.paragraphIndex >= 0 && revision.paragraphIndex < paragraphIndices.count {
  1359→                let actualIndex = paragraphIndices[revision.paragraphIndex]
  1360→                if case .paragraph(var para) = body.children[actualIndex] {
  1361→                    // 移除插入的文字
  1362→                    if let newText = revision.newText {
  1363→                        for j in 0..<para.runs.count {
  1364→                            para.runs[j].text = para.runs[j].text.replacingOccurrences(of: newText, with: "")
  1365→                        }
  1366→                    }
  1367→                    body.children[actualIndex] = .paragraph(para)
  1368→                }
  1369→            }
  1370→        case .deletion:
  1371→            // 拒絕刪除：恢復被刪除的文字（文字已在標記中，移除標記即可）
  1372→            break
  1373→        case .formatting, .paragraphChange, .formatChange:
  1374→            // 拒絕格式變更：恢復原格式（需要實作格式恢復邏輯）
  1375→            break
  1376→        case .moveFrom, .moveTo:
  1377→            // 拒絕移動：恢復原位置的文字
  1378→            break
  1379→        }
  1380→
  1381→        // 移除修訂記錄
  1382→        revisions.revisions.remove(at: index)
  1383→    }
  1384→
  1385→    /// 接受所有修訂
  1386→    public mutating func acceptAllRevisions() {
  1387→        // 從後往前接受，避免索引問題
  1388→        for revision in revisions.revisions.reversed() {
  1389→            try? acceptRevision(revisionId: revision.id)
  1390→        }
  1391→    }
  1392→
  1393→    /// 拒絕所有修訂
  1394→    public mutating func rejectAllRevisions() {
  1395→        // 從後往前拒絕，避免索引問題
  1396→        for revision in revisions.revisions.reversed() {
  1397→            try? rejectRevision(revisionId: revision.id)
  1398→        }
  1399→    }
