  1503→    public mutating func deleteEndnote(endnoteId: Int) throws {
  1504→        guard let index = endnotes.endnotes.firstIndex(where: { $0.id == endnoteId }) else {
  1505→            throw EndnoteError.notFound(endnoteId)
  1506→        }
  1507→
  1508→        // 從段落中移除尾註參照
  1509→        let paragraphIndex = endnotes.endnotes[index].paragraphIndex
  1510→        let paragraphIndices = body.children.enumerated().compactMap { (i, child) -> Int? in
  1511→            if case .paragraph = child { return i }
  1512→            return nil
  1513→        }
  1514→
  1515→        if paragraphIndex >= 0 && paragraphIndex < paragraphIndices.count {
  1516→            let actualIndex = paragraphIndices[paragraphIndex]
  1517→            if case .paragraph(var para) = body.children[actualIndex] {
  1518→                para.endnoteIds.removeAll { $0 == endnoteId }
  1519→                body.children[actualIndex] = .paragraph(para)
  1520→            }
  1521→        }
  1522→
  1523→        endnotes.endnotes.remove(at: index)
  1524→    }
