            sectionProperties.pageSize = sectionProperties.pageSize.landscape
        } else if orientation == .portrait && sectionProperties.pageSize.width > sectionProperties.pageSize.height {
            sectionProperties.pageSize = sectionProperties.pageSize.landscape
        }
    }

