// MARK: - Body Parsing

private static func parseBody(from xml: XMLDocument) throws -> Body {
    var body = Body()

    // 取得所有段落和表格節點
    // XPath: //w:body/*
    let bodyNodes = try xml.nodes(forXPath: "//*[local-name()='body']/*")

