// MARK: - Run Parsing

private static func parseRun(from element: XMLElement, relationships: RelationshipsCollection) throws -> Run {
    var run = Run(text: "")

    // 解析 Run 屬性
    if let rPr = element.elements(forName: "w:rPr").first {
