Now I have a comprehensive understanding of the codebase. Let me provide a detailed semantic annotation architecture design.

---

# Semantic Annotation Architecture Design for ooxml-swift

## Executive Summary

After exploring the codebase, I have designed a semantic annotation architecture that integrates with the existing ooxml-swift library structure. The design addresses the need to annotate Word document elements during parsing so that converters can directly use these annotations without needing to infer element types.

---

## 1. Current Architecture Analysis

### Existing Structure
```
WordDocument
  └── body: Body
        └── children: [BodyChild]
              ├── .paragraph(Paragraph)
              │     ├── runs: [Run]
              │     │     ├── text: String
              │     │     ├── drawing: Drawing?
              │     │     └── rawXML: String? (used for OMML formulas)
              │     └── properties: ParagraphProperties
              │           └── style: String? (for heading detection)
              └── .table(Table)
                    └── rows: [TableRow]
                          └── cells: [TableCell]
```

### Key Observations
1. **Style-based heading detection**: Currently relies on `paragraph.properties.style` matching patterns like "Heading1", "heading 1", etc.
2. **OMML formulas**: Stored in `Run.rawXML` but not semantically tagged
3. **Images**: Stored in `Run.drawing` but not distinguished from formula images
4. **Lists**: Determined by `paragraph.properties.numbering` at runtime
5. **No semantic metadata layer**: Converters must infer element types on-the-fly

---

## 2. Proposed Semantic Annotation Design

### 2.1 Core Semantic Types Enum

```swift
// File: Sources/OOXMLSwift/Models/SemanticAnnotation.swift

import Foundation

/// Semantic element type for Word document elements
public enum SemanticElementType: Equatable, Hashable {
    // Structural elements
    case heading(level: Int)           // 1-6
    case paragraph                      // Regular paragraph
    case title                         // Document title
    case subtitle                      // Document subtitle

    // List elements
    case bulletListItem(level: Int)    // Bullet list item (0-8)
    case numberedListItem(level: Int)  // Numbered list item (0-8)

    // Table elements
    case table
    case tableHeader                   // Header row
    case tableRow                      // Data row
    case tableCell

    // Rich content
    case formula(FormulaType)          // Mathematical formula
    case image(ImageClassification)    // Image with classification
    case codeBlock                     // Code block (if detectable)
    case blockquote                    // Block quote

    // Special elements
    case pageBreak
    case sectionBreak
    case tableOfContents
    case footnote
    case endnote
    case hyperlink
    case bookmark

    // Unknown/ambiguous
    case unknown(hint: String?)        // For elements that need further analysis
}

/// Formula type classification
public enum FormulaType: Equatable, Hashable {
    case omml                          // Native Office Math Markup Language
    case image(confidence: Float)      // Formula rendered as image
    case mathType                      // MathType OLE object
    case latex                         // LaTeX (if embedded)
    case unknown                       // Needs classification
}

/// Image classification for content analysis
public enum ImageClassification: Equatable, Hashable {
    case photo                         // Photograph
    case diagram                       // Diagram/chart
    case screenshot                    // Screenshot
    case formulaImage(confidence: Float) // Likely a formula image
    case icon                          // Small icon
    case decoration                    // Decorative element
    case unknown                       // Needs classification

    /// Convenience property to check if classification is pending
    public var needsClassification: Bool {
        if case .unknown = self { return true }
        return false
    }
}
```

### 2.2 Semantic Annotation Container

```swift
/// Semantic annotation container for document elements
public struct SemanticAnnotation: Equatable {
    /// Primary semantic type
    public var type: SemanticElementType

    /// Confidence level (0.0 - 1.0) for inferred annotations
    public var confidence: Float

    /// Source of the annotation
    public var source: AnnotationSource

    /// Additional metadata
    public var metadata: [String: String]

    public init(
        type: SemanticElementType,
        confidence: Float = 1.0,
        source: AnnotationSource = .parsed,
        metadata: [String: String] = [:]
    ) {
        self.type = type
        self.confidence = confidence
        self.source = source
        self.metadata = metadata
    }

    /// Factory methods for common annotations
    public static func heading(_ level: Int, fromStyle style: String) -> SemanticAnnotation {
        SemanticAnnotation(
            type: .heading(level: level),
            confidence: 1.0,
            source: .parsed,
            metadata: ["originalStyle": style]
        )
    }

    public static func ommlFormula() -> SemanticAnnotation {
        SemanticAnnotation(type: .formula(.omml), confidence: 1.0, source: .parsed)
    }

    public static func imageNeedsClassification() -> SemanticAnnotation {
        SemanticAnnotation(
            type: .image(.unknown),
            confidence: 0.0,
            source: .pending
        )
    }

    public static func unknown(hint: String? = nil) -> SemanticAnnotation {
        SemanticAnnotation(type: .unknown(hint: hint), confidence: 0.0, source: .pending)
    }
}

/// Source of semantic annotation
public enum AnnotationSource: Equatable {
    case parsed        // Determined during OOXML parsing
    case inferred      // Inferred from context/heuristics
    case classified    // Classified by external classifier
    case manual        // Manually specified
    case pending       // Awaiting classification
}
```

### 2.3 Integration with Existing Models

```swift
// MARK: - Paragraph Extensions

extension Paragraph {
    /// Semantic annotation for this paragraph
    public var semantic: SemanticAnnotation?
}

// MARK: - Run Extensions

extension Run {
    /// Semantic annotation for this run (for inline elements like formulas, images)
    public var semantic: SemanticAnnotation?

    /// Check if this run contains a formula
    public var containsFormula: Bool {
        if rawXML?.contains("oMath") == true { return true }
        if case .formula(_) = semantic?.type { return true }
        return false
    }
}

// MARK: - Table Extensions

extension Table {
    /// Semantic annotation for the table
    public var semantic: SemanticAnnotation?
}

extension TableRow {
    /// Semantic annotation for the row
    public var semantic: SemanticAnnotation?
}

extension TableCell {
    /// Semantic annotation for the cell
    public var semantic: SemanticAnnotation?
}

// MARK: - Drawing Extensions (for Images)

extension Drawing {
    /// Semantic classification of the image content
    public var classification: ImageClassification?
}
```

### 2.4 Document-Level Semantic Index

```swift
/// Document-level semantic index for quick lookup
public struct SemanticIndex {
    /// All headings in document order
    public var headings: [(index: Int, level: Int, text: String)] = []

    /// All formulas (both OMML and image-based)
    public var formulas: [FormulaReference] = []

    /// All images with their classifications
    public var images: [ImageAnnotationReference] = []

    /// All tables
    public var tables: [Int] = []  // Indices into body.children

    /// List groups (consecutive list items)
    public var listGroups: [ListGroup] = []

    /// Elements requiring classification
    public var pendingClassification: [PendingElement] = []
}

public struct FormulaReference {
    public var paragraphIndex: Int
    public var runIndex: Int
    public var formulaType: FormulaType
    public var rawContent: String?  // For OMML, the XML; for images, the imageId
}

public struct ImageAnnotationReference {
    public var paragraphIndex: Int
    public var runIndex: Int
    public var imageId: String
    public var classification: ImageClassification
}

public struct ListGroup {
    public var startIndex: Int
    public var endIndex: Int
    public var isBullet: Bool
    public var levels: [Int]
}

public struct PendingElement {
    public var paragraphIndex: Int
    public var runIndex: Int?
    public var elementType: PendingElementType
}

public enum PendingElementType {
    case possibleFormula(imageId: String)
    case ambiguousImage(imageId: String)
    case unknownStyle(styleName: String)
}
```

---

## 3. DocxReader Modifications

### 3.1 Enhanced Parsing with Semantic Annotation

```swift
// File: Sources/OOXMLSwift/IO/DocxReader.swift

extension DocxReader {

    // MARK: - Semantic Paragraph Parsing

    private static func parseParagraphWithSemantics(
        from element: XMLElement,
        styles: [Style],
        numbering: Numbering
    ) throws -> Paragraph {
        var paragraph = try parseParagraph(from: element)

        // Annotate paragraph type
        paragraph.semantic = determineParagraphSemantics(
            paragraph: paragraph,
            styles: styles,
            numbering: numbering
        )

        // Annotate runs
        for i in 0..<paragraph.runs.count {
            paragraph.runs[i].semantic = determineRunSemantics(
                run: paragraph.runs[i]
            )
        }

        return paragraph
    }

    private static func determineParagraphSemantics(
        paragraph: Paragraph,
        styles: [Style],
        numbering: Numbering
    ) -> SemanticAnnotation {

        // 1. Check for heading style
        if let styleName = paragraph.properties.style,
           let level = detectHeadingLevel(styleName: styleName, styles: styles) {
            return .heading(level, fromStyle: styleName)
        }

        // 2. Check for list item
        if let numInfo = paragraph.properties.numbering {
            let isBullet = isListBullet(
                numId: numInfo.numId,
                level: numInfo.level,
                numbering: numbering
            )
            if isBullet {
                return SemanticAnnotation(type: .bulletListItem(level: numInfo.level))
            } else {
                return SemanticAnnotation(type: .numberedListItem(level: numInfo.level))
            }
        }

        // 3. Check for page break
        if paragraph.hasPageBreak {
            return SemanticAnnotation(type: .pageBreak)
        }

        // 4. Check for section break
        if paragraph.properties.sectionBreak != nil {
            return SemanticAnnotation(type: .sectionBreak)
        }

        // 5. Check for special styles (title, subtitle)
        if let styleName = paragraph.properties.style?.lowercased() {
            if styleName == "title" {
                return SemanticAnnotation(type: .title)
            }
            if styleName == "subtitle" {
                return SemanticAnnotation(type: .subtitle)
            }
        }

        // 6. Default to regular paragraph
        return SemanticAnnotation(type: .paragraph)
    }

    private static func determineRunSemantics(run: Run) -> SemanticAnnotation? {
        // 1. Check for OMML formula
        if let rawXML = run.rawXML, rawXML.contains("oMath") {
            return .ommlFormula()
        }

        // 2. Check for drawing/image
        if let drawing = run.drawing {
            // Mark as needing classification
            return .imageNeedsClassification()
        }

        // 3. No special semantic for plain text runs
        return nil
    }

    // MARK: - Heading Detection (enhanced)

    private static func detectHeadingLevel(
        styleName: String,
        styles: [Style]
    ) -> Int? {
        let lowerName = styleName.lowercased()

        // Standard heading patterns
        let patterns: [(pattern: String, level: Int)] = [
            ("heading1", 1), ("heading 1", 1), ("標題 1", 1), ("標題1", 1),
            ("heading2", 2), ("heading 2", 2), ("標題 2", 2), ("標題2", 2),
            ("heading3", 3), ("heading 3", 3), ("標題 3", 3), ("標題3", 3),
            ("heading4", 4), ("heading 4", 4), ("標題 4", 4), ("標題4", 4),
            ("heading5", 5), ("heading 5", 5), ("標題 5", 5), ("標題5", 5),
            ("heading6", 6), ("heading 6", 6), ("標題 6", 6), ("標題6", 6),
        ]

        for (pattern, level) in patterns {
            if lowerName == pattern {
                return level
            }
        }

        // Check style inheritance
        if let style = styles.first(where: { $0.id.lowercased() == lowerName }),
           let basedOn = style.basedOn {
            return detectHeadingLevel(styleName: basedOn, styles: styles)
        }

        return nil
    }
}
```

### 3.2 Building Semantic Index

```swift
extension DocxReader {

    /// Build semantic index after parsing
    public static func buildSemanticIndex(
        from document: WordDocument
    ) -> SemanticIndex {
        var index = SemanticIndex()

        for (i, child) in document.body.children.enumerated() {
            switch child {
            case .paragraph(let para):
                processParagraphForIndex(
                    para,
                    at: i,
                    index: &index
                )

            case .table(let table):
                index.tables.append(i)
            }
        }

        // Group consecutive list items
        index.listGroups = groupListItems(from: document.body.children)

        return index
    }

    private static func processParagraphForIndex(
        _ para: Paragraph,
        at index: Int,
        index semanticIndex: inout SemanticIndex
    ) {
        guard let semantic = para.semantic else { return }

        switch semantic.type {
        case .heading(let level):
            semanticIndex.headings.append((
                index: index,
                level: level,
                text: para.getText()
            ))

        case .formula(let formulaType):
            semanticIndex.formulas.append(FormulaReference(
                paragraphIndex: index,
                runIndex: 0,
                formulaType: formulaType,
                rawContent: nil
            ))

        default:
            break
        }

        // Check runs for formulas and images
        for (runIndex, run) in para.runs.enumerated() {
            if let runSemantic = run.semantic {
                switch runSemantic.type {
                case .formula(let formulaType):
                    semanticIndex.formulas.append(FormulaReference(
                        paragraphIndex: index,
                        runIndex: runIndex,
                        formulaType: formulaType,
                        rawContent: run.rawXML
                    ))

                case .image(let classification):
                    if let imageId = run.drawing?.imageId {
                        semanticIndex.images.append(ImageAnnotationReference(
                            paragraphIndex: index,
                            runIndex: runIndex,
                            imageId: imageId,
                            classification: classification
                        ))

                        // Track pending classifications
                        if classification.needsClassification {
                            semanticIndex.pendingClassification.append(PendingElement(
                                paragraphIndex: index,
                                runIndex: runIndex,
                                elementType: .ambiguousImage(imageId: imageId)
                            ))
                        }
                    }

                default:
                    break
                }
            }
        }
    }
}
```

---

## 4. Converter Integration

### 4.1 Using Semantic Annotations in Converters

```swift
// File: Sources/WordToMD/WordConverter.swift (modified)

public struct WordConverter: DocumentConverter {

    public func convert<W: StreamingOutput>(
        input: URL,
        output: inout W,
        options: ConversionOptions
    ) throws {
        let document = try DocxReader.read(from: input)

        // Build semantic index (optional, for advanced processing)
        let semanticIndex = DocxReader.buildSemanticIndex(from: document)

        for child in document.body.children {
            switch child {
            case .paragraph(let paragraph):
                try processParagraphWithSemantics(
                    paragraph,
                    output: &output,
                    options: options
                )
            case .table(let table):
                try processTable(table, output: &output, options: options)
            }
        }
    }

    private func processParagraphWithSemantics<W: StreamingOutput>(
        _ paragraph: Paragraph,
        output: inout W,
        options: ConversionOptions
    ) throws {
        // Use semantic annotation directly instead of inferring
        guard let semantic = paragraph.semantic else {
            // Fallback to legacy processing if no annotation
            try processLegacyParagraph(paragraph, output: &output, options: options)
            return
        }

        switch semantic.type {
        case .heading(let level):
            let text = formatRuns(paragraph.runs)
            let prefix = String(repeating: "#", count: level)
            try output.writeLine("\(prefix) \(text)")
            try output.writeBlankLine()

        case .bulletListItem(let level):
            let text = formatRuns(paragraph.runs)
            let indent = String(repeating: "  ", count: level)
            try output.writeLine("\(indent)- \(text)")

        case .numberedListItem(let level):
            let text = formatRuns(paragraph.runs)
            let indent = String(repeating: "  ", count: level)
            try output.writeLine("\(indent)1. \(text)")

        case .paragraph:
            let text = formatRuns(paragraph.runs)
            if !text.trimmingCharacters(in: .whitespaces).isEmpty {
                try output.writeLine(text)
                try output.writeBlankLine()
            }

        case .title:
            let text = formatRuns(paragraph.runs)
            try output.writeLine("# \(text)")
            try output.writeBlankLine()

        case .subtitle:
            let text = formatRuns(paragraph.runs)
            try output.writeLine("## \(text)")
            try output.writeBlankLine()

        case .pageBreak, .sectionBreak:
            try output.writeLine("---")
            try output.writeBlankLine()

        default:
            let text = formatRuns(paragraph.runs)
            if !text.isEmpty {
                try output.writeLine(text)
                try output.writeBlankLine()
            }
        }

        // Process runs with semantic annotations (formulas, images)
        for run in paragraph.runs {
            try processRunWithSemantics(run, output: &output, options: options)
        }
    }

    private func processRunWithSemantics<W: StreamingOutput>(
        _ run: Run,
        output: inout W,
        options: ConversionOptions
    ) throws {
        guard let semantic = run.semantic else { return }

        switch semantic.type {
        case .formula(let formulaType):
            switch formulaType {
            case .omml:
                // Convert OMML to LaTeX or render as-is
                if let rawXML = run.rawXML {
                    let latex = convertOMMLToLatex(rawXML)
                    try output.writeLine("$\(latex)$")
                }
            case .image(let confidence):
                if confidence > 0.8 {
                    // High confidence formula image
                    try output.writeLine("![Formula](image.png)")
                } else {
                    // Mark for manual review
                    try output.writeLine("<!-- Possible formula image -->")
                }
            default:
                break
            }

        case .image(let classification):
            switch classification {
            case .formulaImage(let confidence):
                if confidence > 0.8 {
                    try output.writeLine("<!-- Formula as image -->")
                }
            case .unknown:
                // Image needs classification
                try output.writeLine("![Image](image.png) <!-- needs classification -->")
            default:
                if let drawing = run.drawing {
                    try output.writeLine("![Image](\(drawing.name))")
                }
            }

        default:
            break
        }
    }
}
```

---

## 5. Image Classifier Protocol

```swift
// File: Sources/MacDocCore/Protocols/ImageClassifier.swift

/// Protocol for classifying images in Word documents
public protocol ImageClassifier {
    /// Classify an image
    func classify(imageData: Data, context: ImageClassificationContext) async throws -> ImageClassification
}

/// Context for image classification
public struct ImageClassificationContext {
    public var fileName: String
    public var width: Int
    public var height: Int
    public var surroundingText: String?
    public var documentTitle: String?

    public init(
        fileName: String,
        width: Int,
        height: Int,
        surroundingText: String? = nil,
        documentTitle: String? = nil
    ) {
        self.fileName = fileName
        self.width = width
        self.height = height
        self.surroundingText = surroundingText
        self.documentTitle = documentTitle
    }
}

/// Passthrough classifier that marks all images as unknown
public struct PassthroughClassifier: ImageClassifier {
    public init() {}

    public func classify(
        imageData: Data,
        context: ImageClassificationContext
    ) async throws -> ImageClassification {
        return .unknown
    }
}

/// Heuristic-based classifier for simple detection
public struct HeuristicImageClassifier: ImageClassifier {
    public init() {}

    public func classify(
        imageData: Data,
        context: ImageClassificationContext
    ) async throws -> ImageClassification {
        // Small images might be formulas
        if context.width < 400 && context.height < 200 {
            // Check aspect ratio (formulas tend to be wide and short)
            let aspectRatio = Float(context.width) / Float(context.height)
            if aspectRatio > 2.0 && aspectRatio < 10.0 {
                return .formulaImage(confidence: 0.6)
            }
        }

        // Check filename hints
        let lowerName = context.fileName.lowercased()
        if lowerName.contains("formula") || lowerName.contains("equation") {
            return .formulaImage(confidence: 0.8)
        }

        // Large images are likely photos or diagrams
        if context.width > 800 || context.height > 600 {
            return .photo
        }

        return .unknown
    }
}
