## 3. DocxReader Modifications

### 3.1 Enhanced Parsing with Semantic Annotation

```swift
// File: Sources/OOXMLSwift/IO/DocxReader.swift

extension DocxReader {

    // MARK: - Semantic Paragraph Parsing

    private static func parseParagraphWithSemantics(
        from element: XMLElement,
        styles: [Style],
        numbering: Numbering
    ) throws -> Paragraph {
        var paragraph = try parseParagraph(from: element)

        // Annotate paragraph type
        paragraph.semantic = determineParagraphSemantics(
            paragraph: paragraph,
            styles: styles,
            numbering: numbering
        )

        // Annotate runs
        for i in 0..<paragraph.runs.count {
            paragraph.runs[i].semantic = determineRunSemantics(
                run: paragraph.runs[i]
            )
        }

        return paragraph
    }

    private static func determineParagraphSemantics(
        paragraph: Paragraph,
        styles: [Style],
        numbering: Numbering
    ) -> SemanticAnnotation {

        // 1. Check for heading style
        if let styleName = paragraph.properties.style,
           let level = detectHeadingLevel(styleName: styleName, styles: styles) {
            return .heading(level, fromStyle: styleName)
        }

        // 2. Check for list item
        if let numInfo = paragraph.properties.numbering {
            let isBullet = isListBullet(
                numId: numInfo.numId,
                level: numInfo.level,
                numbering: numbering
            )
            if isBullet {
                return SemanticAnnotation(type: .bulletListItem(level: numInfo.level))
            } else {
                return SemanticAnnotation(type: .numberedListItem(level: numInfo.level))
            }
        }

        // 3. Check for page break
        if paragraph.hasPageBreak {
            return SemanticAnnotation(type: .pageBreak)
        }

        // 4. Check for section break
        if paragraph.properties.sectionBreak != nil {
            return SemanticAnnotation(type: .sectionBreak)
        }

        // 5. Check for special styles (title, subtitle)
        if let styleName = paragraph.properties.style?.lowercased() {
            if styleName == "title" {
                return SemanticAnnotation(type: .title)
            }
            if styleName == "subtitle" {
                return SemanticAnnotation(type: .subtitle)
            }
        }

        // 6. Default to regular paragraph
        return SemanticAnnotation(type: .paragraph)
    }

    private static func determineRunSemantics(run: Run) -> SemanticAnnotation? {
        // 1. Check for OMML formula
        if let rawXML = run.rawXML, rawXML.contains("oMath") {
            return .ommlFormula()
        }

        // 2. Check for drawing/image
        if let drawing = run.drawing {
            // Mark as needing classification
            return .imageNeedsClassification()
        }

        // 3. No special semantic for plain text runs
        return nil
    }

    // MARK: - Heading Detection (enhanced)

    private static func detectHeadingLevel(
        styleName: String,
        styles: [Style]
    ) -> Int? {
        let lowerName = styleName.lowercased()

        // Standard heading patterns
        let patterns: [(pattern: String, level: Int)] = [
            ("heading1", 1), ("heading 1", 1), ("標題 1", 1), ("標題1", 1),
            ("heading2", 2), ("heading 2", 2), ("標題 2", 2), ("標題2", 2),
            ("heading3", 3), ("heading 3", 3), ("標題 3", 3), ("標題3", 3),
            ("heading4", 4), ("heading 4", 4), ("標題 4", 4), ("標題4", 4),
            ("heading5", 5), ("heading 5", 5), ("標題 5", 5), ("標題5", 5),
            ("heading6", 6), ("heading 6", 6), ("標題 6", 6), ("標題6", 6),
        ]

        for (pattern, level) in patterns {
            if lowerName == pattern {
                return level
            }
        }

        // Check style inheritance
        if let style = styles.first(where: { $0.id.lowercased() == lowerName }),
           let basedOn = style.basedOn {
            return detectHeadingLevel(styleName: basedOn, styles: styles)
        }

        return nil
    }
}
```

### 3.2 Building Semantic Index

```swift
extension DocxReader {

    /// Build semantic index after parsing
    public static func buildSemanticIndex(
        from document: WordDocument
    ) -> SemanticIndex {
        var index = SemanticIndex()

        for (i, child) in document.body.children.enumerated() {
            switch child {
            case .paragraph(let para):
                processParagraphForIndex(
                    para,
                    at: i,
                    index: &index
                )

            case .table(let table):
                index.tables.append(i)
            }
        }

        // Group consecutive list items
        index.listGroups = groupListItems(from: document.body.children)

        return index
    }

    private static func processParagraphForIndex(
        _ para: Paragraph,
        at index: Int,
        index semanticIndex: inout SemanticIndex
    ) {
        guard let semantic = para.semantic else { return }

        switch semantic.type {
        case .heading(let level):
            semanticIndex.headings.append((
                index: index,
                level: level,
                text: para.getText()
            ))

        case .formula(let formulaType):
            semanticIndex.formulas.append(FormulaReference(
                paragraphIndex: index,
                runIndex: 0,
                formulaType: formulaType,
                rawContent: nil
            ))

        default:
            break
        }

        // Check runs for formulas and images
        for (runIndex, run) in para.runs.enumerated() {
            if let runSemantic = run.semantic {
                switch runSemantic.type {
                case .formula(let formulaType):
                    semanticIndex.formulas.append(FormulaReference(
                        paragraphIndex: index,
                        runIndex: runIndex,
                        formulaType: formulaType,
                        rawContent: run.rawXML
                    ))

                case .image(let classification):
                    if let imageId = run.drawing?.imageId {
                        semanticIndex.images.append(ImageAnnotationReference(
                            paragraphIndex: index,
                            runIndex: runIndex,
                            imageId: imageId,
                            classification: classification
                        ))

                        // Track pending classifications
                        if classification.needsClassification {
                            semanticIndex.pendingClassification.append(PendingElement(
                                paragraphIndex: index,
                                runIndex: runIndex,
                                elementType: .ambiguousImage(imageId: imageId)
                            ))
                        }
                    }

                default:
                    break
                }
            }
        }
    }
}
```

