## 4. Converter Integration

### 4.1 Using Semantic Annotations in Converters

```swift
// File: Sources/WordToMD/WordConverter.swift (modified)

public struct WordConverter: DocumentConverter {

    public func convert<W: StreamingOutput>(
        input: URL,
        output: inout W,
        options: ConversionOptions
    ) throws {
        let document = try DocxReader.read(from: input)

        // Build semantic index (optional, for advanced processing)
        let semanticIndex = DocxReader.buildSemanticIndex(from: document)

        for child in document.body.children {
            switch child {
            case .paragraph(let paragraph):
                try processParagraphWithSemantics(
                    paragraph,
                    output: &output,
                    options: options
                )
            case .table(let table):
                try processTable(table, output: &output, options: options)
            }
        }
    }

    private func processParagraphWithSemantics<W: StreamingOutput>(
        _ paragraph: Paragraph,
        output: inout W,
        options: ConversionOptions
    ) throws {
        // Use semantic annotation directly instead of inferring
        guard let semantic = paragraph.semantic else {
            // Fallback to legacy processing if no annotation
            try processLegacyParagraph(paragraph, output: &output, options: options)
            return
        }

        switch semantic.type {
        case .heading(let level):
            let text = formatRuns(paragraph.runs)
            let prefix = String(repeating: "#", count: level)
            try output.writeLine("\(prefix) \(text)")
            try output.writeBlankLine()

        case .bulletListItem(let level):
            let text = formatRuns(paragraph.runs)
            let indent = String(repeating: "  ", count: level)
            try output.writeLine("\(indent)- \(text)")

        case .numberedListItem(let level):
            let text = formatRuns(paragraph.runs)
            let indent = String(repeating: "  ", count: level)
            try output.writeLine("\(indent)1. \(text)")

        case .paragraph:
            let text = formatRuns(paragraph.runs)
            if !text.trimmingCharacters(in: .whitespaces).isEmpty {
                try output.writeLine(text)
                try output.writeBlankLine()
            }

        case .title:
            let text = formatRuns(paragraph.runs)
            try output.writeLine("# \(text)")
            try output.writeBlankLine()

        case .subtitle:
            let text = formatRuns(paragraph.runs)
            try output.writeLine("## \(text)")
            try output.writeBlankLine()

        case .pageBreak, .sectionBreak:
            try output.writeLine("---")
            try output.writeBlankLine()

        default:
            let text = formatRuns(paragraph.runs)
            if !text.isEmpty {
                try output.writeLine(text)
                try output.writeBlankLine()
            }
        }

        // Process runs with semantic annotations (formulas, images)
        for run in paragraph.runs {
            try processRunWithSemantics(run, output: &output, options: options)
        }
    }

    private func processRunWithSemantics<W: StreamingOutput>(
        _ run: Run,
        output: inout W,
        options: ConversionOptions
    ) throws {
        guard let semantic = run.semantic else { return }

        switch semantic.type {
        case .formula(let formulaType):
            switch formulaType {
            case .omml:
                // Convert OMML to LaTeX or render as-is
                if let rawXML = run.rawXML {
                    let latex = convertOMMLToLatex(rawXML)
                    try output.writeLine("$\(latex)$")
                }
            case .image(let confidence):
                if confidence > 0.8 {
                    // High confidence formula image
                    try output.writeLine("![Formula](image.png)")
                } else {
                    // Mark for manual review
                    try output.writeLine("<!-- Possible formula image -->")
                }
            default:
                break
            }

        case .image(let classification):
            switch classification {
            case .formulaImage(let confidence):
                if confidence > 0.8 {
                    try output.writeLine("<!-- Formula as image -->")
                }
            case .unknown:
                // Image needs classification
                try output.writeLine("![Image](image.png) <!-- needs classification -->")
            default:
                if let drawing = run.drawing {
                    try output.writeLine("![Image](\(drawing.name))")
                }
            }

        default:
            break
        }
    }
}
