/// Protocol for classifying images in Word documents
public protocol ImageClassifier {
    /// Classify an image
    func classify(imageData: Data, context: ImageClassificationContext) async throws -> ImageClassification
}

/// Context for image classification
public struct ImageClassificationContext {
    public var fileName: String
    public var width: Int
    public var height: Int
    public var surroundingText: String?
    public var documentTitle: String?

    public init(
        fileName: String,
        width: Int,
        height: Int,
        surroundingText: String? = nil,
        documentTitle: String? = nil
    ) {
        self.fileName = fileName
        self.width = width
        self.height = height
        self.surroundingText = surroundingText
        self.documentTitle = documentTitle
    }
}

/// Passthrough classifier that marks all images as unknown
public struct PassthroughClassifier: ImageClassifier {
    public init() {}

    public func classify(
        imageData: Data,
        context: ImageClassificationContext
    ) async throws -> ImageClassification {
        return .unknown
    }
}

/// Heuristic-based classifier for simple detection
public struct HeuristicImageClassifier: ImageClassifier {
    public init() {}

    public func classify(
        imageData: Data,
        context: ImageClassificationContext
    ) async throws -> ImageClassification {
        // Small images might be formulas
        if context.width < 400 && context.height < 200 {
            // Check aspect ratio (formulas tend to be wide and short)
            let aspectRatio = Float(context.width) / Float(context.height)
            if aspectRatio > 2.0 && aspectRatio < 10.0 {
                return .formulaImage(confidence: 0.6)
            }
        }

        // Check filename hints
        let lowerName = context.fileName.lowercased()
        if lowerName.contains("formula") || lowerName.contains("equation") {
            return .formulaImage(confidence: 0.8)
        }

        // Large images are likely photos or diagrams
        if context.width > 800 || context.height > 600 {
            return .photo
        }

        return .unknown
    }
}
