import Foundation

/// 文字運行 (Run) - Word 文件中的最小文字單元
/// 一個 Run 包含具有相同格式的連續文字
public struct Run {
    public var text: String
    public var properties: RunProperties
    public var drawing: Drawing?  // 圖片繪圖元素
    public var rawXML: String?    // 原始 XML（用於欄位代碼、SDT 等進階功能）

    public init(text: String, properties: RunProperties = RunProperties()) {
        self.text = text
        self.properties = properties
        self.drawing = nil
        self.rawXML = nil
    }
}

// MARK: - Run Properties

/// Run 格式屬性
public struct RunProperties {
    public var bold: Bool = false
    public var italic: Bool = false
    public var underline: UnderlineType?
    public var strikethrough: Bool = false
    public var fontSize: Int?              // 半點 (24 = 12pt)
    public var fontName: String?
    public var color: String?              // RGB hex (e.g., "FF0000")
    public var highlight: HighlightColor?
    public var verticalAlign: VerticalAlign?
    public var characterSpacing: CharacterSpacing?  // 字元間距
    public var textEffect: TextEffect?              // 文字效果
    public var rawXML: String?                      // 原始 XML（用於進階功能如 SDT）

    public init() {}

    public init(bold: Bool = false,
         italic: Bool = false,
         underline: UnderlineType? = nil,
         strikethrough: Bool = false,
         fontSize: Int? = nil,
         fontName: String? = nil,
         color: String? = nil,
         highlight: HighlightColor? = nil,
         verticalAlign: VerticalAlign? = nil) {
        self.bold = bold
        self.italic = italic
        self.underline = underline
        self.strikethrough = strikethrough
        self.fontSize = fontSize
        self.fontName = fontName
        self.color = color
        self.highlight = highlight
        self.verticalAlign = verticalAlign
    }

    /// 合併格式（覆蓋非 nil 值）
    mutating func merge(with other: RunProperties) {
        if other.bold { self.bold = true }
        if other.italic { self.italic = true }
        if let underline = other.underline { self.underline = underline }
        if other.strikethrough { self.strikethrough = true }
        if let fontSize = other.fontSize { self.fontSize = fontSize }
        if let fontName = other.fontName { self.fontName = fontName }
        if let color = other.color { self.color = color }
        if let highlight = other.highlight { self.highlight = highlight }
        if let verticalAlign = other.verticalAlign { self.verticalAlign = verticalAlign }
        if let characterSpacing = other.characterSpacing { self.characterSpacing = characterSpacing }
        if let textEffect = other.textEffect { self.textEffect = textEffect }
        if let rawXML = other.rawXML { self.rawXML = rawXML }
    }
}

// MARK: - Enums

/// 底線類型
public enum UnderlineType: String, Codable {
    case single = "single"
    case double = "double"
    case dotted = "dotted"
    case dashed = "dash"
    case wave = "wave"
    case thick = "thick"
    case words = "words"        // 只在文字下，空格無底線
}

/// 螢光標記顏色
public enum HighlightColor: String, Codable {
    case yellow = "yellow"
    case green = "green"
    case cyan = "cyan"
    case magenta = "magenta"
    case blue = "blue"
    case red = "red"
    case darkBlue = "darkBlue"
    case darkCyan = "darkCyan"
    case darkGreen = "darkGreen"
    case darkMagenta = "darkMagenta"
    case darkRed = "darkRed"
    case darkYellow = "darkYellow"
    case lightGray = "lightGray"
    case darkGray = "darkGray"
    case black = "black"
    case white = "white"
}

/// 垂直對齊（上標/下標）
public enum VerticalAlign: String, Codable {
    case superscript = "superscript"
    case `subscript` = "subscript"
    case baseline = "baseline"
}

// MARK: - XML 生成

extension Run {
    /// 轉換為 OOXML XML 字串
    func toXML() -> String {
        // 如果 Run 本身有原始 XML，直接輸出（用於欄位代碼、SDT 等）
        if let rawXML = self.rawXML {
            return rawXML
        }

        // 如果 RunProperties 有原始 XML，也直接輸出
        if let rawXML = properties.rawXML {
            return rawXML
        }

        var xml = "<w:r>"

        // Run Properties
        let propsXML = properties.toXML()
        if !propsXML.isEmpty {
            xml += "<w:rPr>\(propsXML)</w:rPr>"
        }

        // Drawing (圖片) - 如果有圖片，優先輸出圖片
        if let drawing = drawing {
            xml += drawing.toXML()
        } else {
            // Text (保留空格)
            xml += "<w:t xml:space=\"preserve\">\(escapeXML(text))</w:t>"
        }

        xml += "</w:r>"

        return xml
    }

    private func escapeXML(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }
}

extension RunProperties {
    /// 轉換為 OOXML XML 字串
    func toXML() -> String {
        var parts: [String] = []

        if bold {
            parts.append("<w:b/>")
        }
        if italic {
            parts.append("<w:i/>")
        }
        if let underline = underline {
            parts.append("<w:u w:val=\"\(underline.rawValue)\"/>")
        }
        if strikethrough {
            parts.append("<w:strike/>")
        }
        if let fontSize = fontSize {
            // OOXML 使用半點 (half-points)
            parts.append("<w:sz w:val=\"\(fontSize)\"/>")
            parts.append("<w:szCs w:val=\"\(fontSize)\"/>")  // 複雜文字大小
        }
        if let fontName = fontName {
            parts.append("<w:rFonts w:ascii=\"\(fontName)\" w:hAnsi=\"\(fontName)\" w:eastAsia=\"\(fontName)\" w:cs=\"\(fontName)\"/>")
        }
        if let color = color {
            parts.append("<w:color w:val=\"\(color)\"/>")
        }
        if let highlight = highlight {
            parts.append("<w:highlight w:val=\"\(highlight.rawValue)\"/>")
        }
        if let verticalAlign = verticalAlign {
            parts.append("<w:vertAlign w:val=\"\(verticalAlign.rawValue)\"/>")
        }
        if let characterSpacing = characterSpacing {
            parts.append(characterSpacing.toXML())
        }
        if let textEffect = textEffect {
            parts.append(textEffect.toXML())
        }

        return parts.joined()
    }
}

import Foundation

// MARK: - Table of Contents (TOC)

/// 目錄欄位
public struct TableOfContents {
    public var title: String?                  // 目錄標題
    public var headingLevels: ClosedRange<Int> // 包含的標題層級 (1-9)
    public var includePageNumbers: Bool        // 是否包含頁碼
    public var rightAlignPageNumbers: Bool     // 頁碼是否右對齊
    public var useHyperlinks: Bool             // 是否使用超連結
    public var tabLeader: TabLeader            // 定位線類型

    public init(
        title: String? = nil,
        headingLevels: ClosedRange<Int> = 1...3,
        includePageNumbers: Bool = true,
        rightAlignPageNumbers: Bool = true,
        useHyperlinks: Bool = true,
        tabLeader: TabLeader = .dot
    ) {
        self.title = title
        self.headingLevels = headingLevels
        self.includePageNumbers = includePageNumbers
        self.rightAlignPageNumbers = rightAlignPageNumbers
        self.useHyperlinks = useHyperlinks
        self.tabLeader = tabLeader
    }
}

/// 定位線類型
public enum TabLeader: String, Codable {
    case none = "none"
    case dot = "dot"
    case hyphen = "hyphen"
    case underscore = "underscore"
}

// MARK: - TOC XML Generation

extension TableOfContents {
    /// 產生目錄欄位的 XML
    func toXML() -> String {
        var xml = ""

        // 目錄標題（如果有）
        if let title = title {
            xml += """
            <w:p>
                <w:pPr>
                    <w:pStyle w:val="TOCHeading"/>
                </w:pPr>
                <w:r>
                    <w:t>\(escapeXML(title))</w:t>
                </w:r>
            </w:p>
            """
        }

        // 目錄開始 - 使用 SDT (Structured Document Tag)
        xml += """
        <w:sdt>
            <w:sdtPr>
                <w:docPartObj>
                    <w:docPartGallery w:val="Table of Contents"/>
                    <w:docPartUnique/>
                </w:docPartObj>
            </w:sdtPr>
            <w:sdtContent>
        """

        // 目錄欄位開始
        xml += """
            <w:p>
                <w:r>
                    <w:fldChar w:fldCharType="begin"/>
                </w:r>
                <w:r>
                    <w:instrText xml:space="preserve"> TOC \\o "\(headingLevels.lowerBound)-\(headingLevels.upperBound)"</w:instrText>
                </w:r>
        """

        // 欄位選項
        if useHyperlinks {
            xml += """
                <w:r>
                    <w:instrText xml:space="preserve"> \\h</w:instrText>
                </w:r>
            """
        }

        if !includePageNumbers {
            xml += """
                <w:r>
                    <w:instrText xml:space="preserve"> \\n</w:instrText>
                </w:r>
            """
        }

        // 欄位分隔和結束
        xml += """
                <w:r>
                    <w:fldChar w:fldCharType="separate"/>
                </w:r>
                <w:r>
                    <w:t>Update this field to generate table of contents.</w:t>
                </w:r>
                <w:r>
                    <w:fldChar w:fldCharType="end"/>
                </w:r>
            </w:p>
        """

        // SDT 結束
        xml += """
            </w:sdtContent>
        </w:sdt>
        """

        return xml
    }

    private func escapeXML(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }
}

// MARK: - Form Controls

/// 表單文字欄位
public struct FormTextField {
    public var name: String                // 欄位名稱
    public var defaultValue: String?       // 預設值
    public var maxLength: Int?             // 最大長度
    public var helpText: String?           // 說明文字

    public init(name: String, defaultValue: String? = nil, maxLength: Int? = nil, helpText: String? = nil) {
        self.name = name
        self.defaultValue = defaultValue
        self.maxLength = maxLength
        self.helpText = helpText
    }
}

extension FormTextField {
    /// 產生表單文字欄位的 XML
    func toXML() -> String {
        var xml = "<w:sdt>"

        // SDT 屬性
        xml += "<w:sdtPr>"
        xml += "<w:alias w:val=\"\(escapeXML(name))\"/>"
        xml += "<w:tag w:val=\"\(escapeXML(name))\"/>"
        xml += "<w:text/>"
        xml += "</w:sdtPr>"

        // SDT 內容
        xml += "<w:sdtContent>"
        xml += "<w:r>"
        if let value = defaultValue {
            xml += "<w:t>\(escapeXML(value))</w:t>"
        } else {
            xml += "<w:t>          </w:t>"  // 空白佔位
        }
        xml += "</w:r>"
        xml += "</w:sdtContent>"

        xml += "</w:sdt>"
        return xml
    }

    private func escapeXML(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }
}

/// 核取方塊
public struct FormCheckbox {
    public var name: String            // 欄位名稱
    public var isChecked: Bool         // 是否勾選
    public var checkedSymbol: String   // 勾選時的符號
    public var uncheckedSymbol: String // 未勾選時的符號

    public init(name: String, isChecked: Bool = false, checkedSymbol: String = "☒", uncheckedSymbol: String = "☐") {
        self.name = name
        self.isChecked = isChecked
        self.checkedSymbol = checkedSymbol
        self.uncheckedSymbol = uncheckedSymbol
    }
}

extension FormCheckbox {
    /// 產生核取方塊的 XML
    func toXML() -> String {
        var xml = "<w:sdt>"

        // SDT 屬性
        xml += "<w:sdtPr>"
        xml += "<w:alias w:val=\"\(escapeXML(name))\"/>"
        xml += "<w:tag w:val=\"\(escapeXML(name))\"/>"
        xml += "<w14:checkbox xmlns:w14=\"http://schemas.microsoft.com/office/word/2010/wordml\">"
        xml += "<w14:checked w14:val=\"\(isChecked ? "1" : "0")\"/>"
        xml += "<w14:checkedState w14:val=\"2612\" w14:font=\"MS Gothic\"/>"
        xml += "<w14:uncheckedState w14:val=\"2610\" w14:font=\"MS Gothic\"/>"
        xml += "</w14:checkbox>"
        xml += "</w:sdtPr>"

        // SDT 內容
        xml += "<w:sdtContent>"
        xml += "<w:r>"
        xml += "<w:rPr><w:rFonts w:ascii=\"MS Gothic\" w:hAnsi=\"MS Gothic\" w:hint=\"eastAsia\"/></w:rPr>"
        xml += "<w:t>\(isChecked ? "☒" : "☐")</w:t>"
        xml += "</w:r>"
        xml += "</w:sdtContent>"

        xml += "</w:sdt>"
        return xml
    }

    private func escapeXML(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }
}

/// 下拉選單
public struct FormDropdown {
    public var name: String            // 欄位名稱
    public var options: [String]       // 選項列表
    public var selectedIndex: Int      // 選中的索引

    public init(name: String, options: [String], selectedIndex: Int = 0) {
        self.name = name
        self.options = options
        self.selectedIndex = min(selectedIndex, options.count - 1)
    }
}

extension FormDropdown {
    /// 產生下拉選單的 XML
    func toXML() -> String {
        var xml = "<w:sdt>"

        // SDT 屬性
        xml += "<w:sdtPr>"
        xml += "<w:alias w:val=\"\(escapeXML(name))\"/>"
        xml += "<w:tag w:val=\"\(escapeXML(name))\"/>"
        xml += "<w:dropDownList>"
        for (index, option) in options.enumerated() {
            xml += "<w:listItem w:displayText=\"\(escapeXML(option))\" w:value=\"\(index)\"/>"
        }
        xml += "</w:dropDownList>"
        xml += "</w:sdtPr>"

        // SDT 內容
        xml += "<w:sdtContent>"
        xml += "<w:r>"
        let selectedValue = options.indices.contains(selectedIndex) ? options[selectedIndex] : ""
        xml += "<w:t>\(escapeXML(selectedValue))</w:t>"
        xml += "</w:r>"
        xml += "</w:sdtContent>"

        xml += "</w:sdt>"
        return xml
    }

    private func escapeXML(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }
}

// MARK: - Mathematical Equations (OMML)

/// Office 數學公式
public struct MathEquation {
    public var latex: String           // LaTeX 格式的公式
    public var displayMode: Bool       // 是否為獨立區塊（true）或行內（false）

    public init(latex: String, displayMode: Bool = false) {
        self.latex = latex
        self.displayMode = displayMode
    }
}

extension MathEquation {
    /// 產生 OMML 格式的數學公式 XML
    /// 注意：這是簡化版本，僅支援基本公式
    func toXML() -> String {
        // OMML (Office Math Markup Language) 基本結構
        var xml = ""

        if displayMode {
            // 獨立區塊公式
            xml += "<w:p>"
            xml += "<w:pPr><w:jc w:val=\"center\"/></w:pPr>"
        }

        xml += "<m:oMath xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\">"

        // 簡單轉換 LaTeX 到 OMML
        // 這是一個基礎實作，僅支援簡單文字
        let processedText = processLatex(latex)
        xml += "<m:r><m:t>\(escapeXML(processedText))</m:t></m:r>"

        xml += "</m:oMath>"

        if displayMode {
            xml += "</w:p>"
        }

        return xml
    }

    /// 基礎 LaTeX 處理（簡化版）
    private func processLatex(_ latex: String) -> String {
        var result = latex
        // 移除一些 LaTeX 指令，保留內容
        result = result.replacingOccurrences(of: "\\frac{", with: "(")
        result = result.replacingOccurrences(of: "}{", with: ")/(")
        result = result.replacingOccurrences(of: "\\sqrt{", with: "√(")
        result = result.replacingOccurrences(of: "\\sum", with: "∑")
        result = result.replacingOccurrences(of: "\\int", with: "∫")
        result = result.replacingOccurrences(of: "\\alpha", with: "α")
        result = result.replacingOccurrences(of: "\\beta", with: "β")
        result = result.replacingOccurrences(of: "\\gamma", with: "γ")
        result = result.replacingOccurrences(of: "\\pi", with: "π")
        result = result.replacingOccurrences(of: "\\infty", with: "∞")
        result = result.replacingOccurrences(of: "^{", with: "^")
        result = result.replacingOccurrences(of: "_{", with: "_")
        result = result.replacingOccurrences(of: "}", with: "")
        result = result.replacingOccurrences(of: "{", with: "")
        result = result.replacingOccurrences(of: "\\", with: "")
        return result
    }

    private func escapeXML(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&apos;")
    }
}

