   132→    public mutating func replaceText(find: String, with replacement: String, all: Bool) -> Int {
   133→        var count = 0
   134→        for i in 0..<body.children.count {
   135→            if case .paragraph(var para) = body.children[i] {
   136→                for j in 0..<para.runs.count {
   137→                    if para.runs[j].text.contains(find) {
   138→                        if all {
   139→                            let occurrences = para.runs[j].text.components(separatedBy: find).count - 1
   140→                            count += occurrences
   141→                            para.runs[j].text = para.runs[j].text.replacingOccurrences(of: find, with: replacement)
   142→                        } else if count == 0 {
   143→                            if let range = para.runs[j].text.range(of: find) {
   144→                                para.runs[j].text.replaceSubrange(range, with: replacement)
   145→                                count = 1
   146→                            }
   147→                        }
   148→                    }
   149→                }
   150→                body.children[i] = .paragraph(para)
   151→                if !all && count > 0 { break }
   152→            }
   153→        }
   154→        return count
   155→    }
