   287→    /// 合併儲存格（水平合併）
   288→    public mutating func mergeCellsHorizontal(tableIndex: Int, row: Int, startCol: Int, endCol: Int) throws {
   289→        let tableIndices = getTableIndices()
   290→
   291→        guard tableIndex >= 0 && tableIndex < tableIndices.count else {
   292→            throw WordError.invalidIndex(tableIndex)
   293→        }
   294→
   295→        let actualIndex = tableIndices[tableIndex]
   296→        if case .table(var table) = body.children[actualIndex] {
   297→            guard row >= 0 && row < table.rows.count else {
   298→                throw WordError.invalidIndex(row)
   299→            }
   300→            guard startCol >= 0 && startCol < table.rows[row].cells.count else {
   301→                throw WordError.invalidIndex(startCol)
   302→            }
   303→            guard endCol >= startCol && endCol < table.rows[row].cells.count else {
   304→                throw WordError.invalidIndex(endCol)
   305→            }
   306→
   307→            // 設定第一個儲存格的 gridSpan
   308→            let span = endCol - startCol + 1
   309→            table.rows[row].cells[startCol].properties.gridSpan = span
   310→
   311→            // 移除被合併的儲存格（從後往前移除以保持索引正確）
   312→            for col in (startCol + 1...endCol).reversed() {
   313→                table.rows[row].cells.remove(at: col)
   314→            }
   315→
   316→            body.children[actualIndex] = .table(table)
   317→            if tableIndex < body.tables.count {
   318→                body.tables[tableIndex] = table
   319→            }
   320→        }
   321→    }
