   323→    /// 合併儲存格（垂直合併）
   324→    public mutating func mergeCellsVertical(tableIndex: Int, col: Int, startRow: Int, endRow: Int) throws {
   325→        let tableIndices = getTableIndices()
   326→
   327→        guard tableIndex >= 0 && tableIndex < tableIndices.count else {
   328→            throw WordError.invalidIndex(tableIndex)
   329→        }
   330→
   331→        let actualIndex = tableIndices[tableIndex]
   332→        if case .table(var table) = body.children[actualIndex] {
   333→            guard startRow >= 0 && startRow < table.rows.count else {
   334→                throw WordError.invalidIndex(startRow)
   335→            }
   336→            guard endRow >= startRow && endRow < table.rows.count else {
   337→                throw WordError.invalidIndex(endRow)
   338→            }
   339→
   340→            // 設定第一個儲存格為 restart
   341→            if col < table.rows[startRow].cells.count {
   342→                table.rows[startRow].cells[col].properties.verticalMerge = .restart
   343→            }
   344→
   345→            // 設定其餘儲存格為 continue
   346→            for row in (startRow + 1)...endRow {
   347→                if col < table.rows[row].cells.count {
   348→                    table.rows[row].cells[col].properties.verticalMerge = .continue
   349→                }
   350→            }
   351→
   352→            body.children[actualIndex] = .table(table)
   353→            if tableIndex < body.tables.count {
   354→                body.tables[tableIndex] = table
   355→            }
   356→        }
   357→    }
