   414→    /// 新增自訂樣式
   415→    public mutating func addStyle(_ style: Style) throws {
   416→        // 檢查是否已存在相同 ID 的樣式
   417→        if styles.contains(where: { $0.id == style.id }) {
   418→            throw WordError.invalidFormat("Style with id '\(style.id)' already exists")
   419→        }
   420→        styles.append(style)
   421→    }
   422→
   423→    /// 更新樣式
   424→    public mutating func updateStyle(id: String, with updates: StyleUpdate) throws {
   425→        guard let index = styles.firstIndex(where: { $0.id == id }) else {
   426→            throw WordError.invalidFormat("Style '\(id)' not found")
   427→        }
   428→
   429→        var style = styles[index]
   430→
   431→        if let name = updates.name {
   432→            style.name = name
   433→        }
   434→        if let basedOn = updates.basedOn {
   435→            style.basedOn = basedOn
   436→        }
   437→        if let nextStyle = updates.nextStyle {
   438→            style.nextStyle = nextStyle
   439→        }
   440→        if let isQuickStyle = updates.isQuickStyle {
   441→            style.isQuickStyle = isQuickStyle
   442→        }
   443→        if let paragraphProps = updates.paragraphProperties {
   444→            if style.paragraphProperties == nil {
   445→                style.paragraphProperties = ParagraphProperties()
   446→            }
   447→            style.paragraphProperties?.merge(with: paragraphProps)
   448→        }
   449→        if let runProps = updates.runProperties {
   450→            if style.runProperties == nil {
   451→                style.runProperties = RunProperties()
   452→            }
   453→            style.runProperties?.merge(with: runProps)
   454→        }
   455→
   456→        styles[index] = style
   457→    }
   458→
   459→    /// 刪除樣式（不能刪除預設樣式）
   460→    public mutating func deleteStyle(id: String) throws {
   461→        guard let index = styles.firstIndex(where: { $0.id == id }) else {
   462→            throw WordError.invalidFormat("Style '\(id)' not found")
   463→        }
   464→
   465→        // 不能刪除預設樣式
   466→        if styles[index].isDefault {
   467→            throw WordError.invalidFormat("Cannot delete default style '\(id)'")
   468→        }
   469→
   470→        // 檢查是否為內建樣式（Normal, Heading1-3, Title, Subtitle）
   471→        let builtInIds = ["Normal", "Heading1", "Heading2", "Heading3", "Title", "Subtitle"]
   472→        if builtInIds.contains(id) {
   473→            throw WordError.invalidFormat("Cannot delete built-in style '\(id)'")
   474→        }
   475→
   476→        styles.remove(at: index)
   477→    }
