   943→    /// 插入外部超連結
   944→    public mutating func insertHyperlink(
   945→        url: String,
   946→        text: String,
   947→        at paragraphIndex: Int? = nil,
   948→        tooltip: String? = nil
   949→    ) -> String {
   950→        let hyperlinkId = "hyperlink_\(nextHyperlinkId)"
   951→        nextHyperlinkId += 1
   952→
   953→        let relationshipId = nextHyperlinkRelationshipId
   954→
   955→        // 建立超連結關係（用於 .rels 檔案）
   956→        let reference = HyperlinkReference(relationshipId: relationshipId, url: url)
   957→        hyperlinkReferences.append(reference)
   958→
   959→        // 建立超連結
   960→        let hyperlink = Hyperlink.external(
   961→            id: hyperlinkId,
   962→            text: text,
   963→            url: url,
   964→            relationshipId: relationshipId,
   965→            tooltip: tooltip
   966→        )
   967→
   968→        // 如果指定了段落索引，加到該段落；否則建立新段落
   969→        if let index = paragraphIndex {
   970→            let paragraphIndices = body.children.enumerated().compactMap { (i, child) -> Int? in
   971→                if case .paragraph = child { return i }
   972→                return nil
   973→            }
   974→
   975→            if index >= 0 && index < paragraphIndices.count {
   976→                let actualIndex = paragraphIndices[index]
   977→                if case .paragraph(var para) = body.children[actualIndex] {
   978→                    para.hyperlinks.append(hyperlink)
   979→                    body.children[actualIndex] = .paragraph(para)
   980→                }
   981→            }
   982→        } else {
   983→            // 建立新段落包含超連結
   984→            var para = Paragraph()
   985→            para.hyperlinks.append(hyperlink)
   986→            appendParagraph(para)
   987→        }
   988→
   989→        return hyperlinkId
   990→    }
