  1032→    /// 更新超連結
  1033→    public mutating func updateHyperlink(hyperlinkId: String, text: String? = nil, url: String? = nil) throws {
  1034→        for i in 0..<body.children.count {
  1035→            if case .paragraph(var para) = body.children[i] {
  1036→                for j in 0..<para.hyperlinks.count {
  1037→                    if para.hyperlinks[j].id == hyperlinkId {
  1038→                        if let newText = text {
  1039→                            para.hyperlinks[j].text = newText
  1040→                        }
  1041→                        if let newUrl = url {
  1042→                            // 更新 URL 需要同時更新 relationship
  1043→                            if let rId = para.hyperlinks[j].relationshipId {
  1044→                                if let refIndex = hyperlinkReferences.firstIndex(where: { $0.relationshipId == rId }) {
  1045→                                    hyperlinkReferences[refIndex].url = newUrl
  1046→                                }
  1047→                            }
  1048→                            para.hyperlinks[j].url = newUrl
  1049→                        }
  1050→                        body.children[i] = .paragraph(para)
  1051→                        return
  1052→                    }
  1053→                }
  1054→            }
  1055→        }
  1056→        throw WordError.invalidFormat("Hyperlink '\(hyperlinkId)' not found")
  1057→    }
  1058→
  1059→    /// 刪除超連結
  1060→    public mutating func deleteHyperlink(hyperlinkId: String) throws {
  1061→        for i in 0..<body.children.count {
  1062→            if case .paragraph(var para) = body.children[i] {
  1063→                if let index = para.hyperlinks.firstIndex(where: { $0.id == hyperlinkId }) {
  1064→                    // 如果是外部連結，也要刪除 relationship
  1065→                    if let rId = para.hyperlinks[index].relationshipId {
  1066→                        hyperlinkReferences.removeAll { $0.relationshipId == rId }
  1067→                    }
  1068→                    para.hyperlinks.remove(at: index)
  1069→                    body.children[i] = .paragraph(para)
  1070→                    return
  1071→                }
  1072→            }
  1073→        }
  1074→        throw WordError.invalidFormat("Hyperlink '\(hyperlinkId)' not found")
  1075→    }
