  1533→    // MARK: - Export
  1534→
  1535→    public func toMarkdown() -> String {
  1536→        var result = ""
  1537→        for child in body.children {
  1538→            switch child {
  1539→            case .paragraph(let para):
  1540→                let text = para.getText()
  1541→                if let style = para.properties.style {
  1542→                    switch style {
  1543→                    case "Heading1", "heading 1":
  1544→                        result += "# \(text)\n\n"
  1545→                    case "Heading2", "heading 2":
  1546→                        result += "## \(text)\n\n"
  1547→                    case "Heading3", "heading 3":
  1548→                        result += "### \(text)\n\n"
  1549→                    case "Title":
  1550→                        result += "# \(text)\n\n"
  1551→                    default:
  1552→                        result += "\(text)\n\n"
  1553→                    }
  1554→                } else {
  1555→                    result += "\(text)\n\n"
  1556→                }
  1557→            case .table(let table):
  1558→                result += table.toMarkdown() + "\n\n"
  1559→            }
  1560→        }
  1561→        return result.trimmingCharacters(in: .whitespacesAndNewlines)
  1562→    }
  1563→}
