**在 parseParagraph 中加入標註邏輯**:
```swift
private static func parseParagraph(from element: XMLElement,
                                   relationships: RelationshipsCollection,
                                   styles: [Style]) throws -> Paragraph {
    var paragraph = Paragraph()

    // 解析段落屬性
    if let pPr = element.elements(forName: "w:pPr").first {
        paragraph.properties = parseParagraphProperties(from: pPr)
    }

    // 🆕 語義標註
    paragraph.semantic = detectParagraphSemantic(
        properties: paragraph.properties,
        styles: styles
    )

    // 解析 Runs
    for run in element.elements(forName: "w:r") {
        let parsedRun = try parseRun(from: run, relationships: relationships)
        paragraph.runs.append(parsedRun)
    }

    // 🆕 檢查是否包含公式 Run，升級段落標註
    if paragraph.runs.contains(where: { $0.semantic?.type == .some(.formula(.omml)) }) {
        paragraph.semantic = .ommlFormula
    }

    return paragraph
}

// 🆕 新增函數
private static func detectParagraphSemantic(
    properties: ParagraphProperties,
    styles: [Style]
) -> SemanticAnnotation? {
    // 1. 檢查標題樣式
    if let styleName = properties.style {
        if let level = headingLevelFromStyle(styleName, styles: styles) {
            return .heading(level)
        }
    }

    // 2. 檢查清單
    if let numInfo = properties.numbering {
        // TODO: 根據 numbering 定義判斷 bullet/numbered
        return .bulletItem(level: numInfo.level)
    }

    // 3. 分頁符
    if properties.pageBreakBefore == true {
        return .pageBreak
    }

    // 4. 預設段落
    return .paragraph
}

private static func headingLevelFromStyle(_ styleName: String,
                                          styles: [Style]) -> Int? {
    let lower = styleName.lowercased()
    let patterns: [(String, Int)] = [
        ("heading1", 1), ("heading 1", 1), ("標題 1", 1), ("標題1", 1),
        ("heading2", 2), ("heading 2", 2), ("標題 2", 2), ("標題2", 2),
        ("heading3", 3), ("heading 3", 3), ("標題 3", 3), ("標題3", 3),
        ("heading4", 4), ("heading5", 5), ("heading6", 6),
        ("title", 1), ("subtitle", 2),
    ]

    for (pattern, level) in patterns {
        if lower == pattern { return level }
    }

    // 檢查樣式繼承
    if let style = styles.first(where: { $0.id.lowercased() == lower }),
       let basedOn = style.basedOn {
        return headingLevelFromStyle(basedOn, styles: styles)
    }

    return nil
}
```

